const RAW_CHAPTERS = [{"num": 1, "arabicTitle": "أَذْكَارُ الاسْتِيقَاظِ مِنَ النَّومِ", "oromoTitle": "Zikrii yeroo hirriba irraa dammaqanuu", "duas": [{"arabic": "((الحَمْدُ للَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ)).", "oromo": "“Faaruun kan Rabbii erga nu ajjeesee fayyisee nu jiraachiseeti.”"}, {"arabic": "((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لهُ الْمُلْكُ وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ\nشَيْءٍ قَدِيرٌ، سُبْحَانَ اللَّهِ، وَالحَمْدُ للَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكبَرُ، وَلاَ حَوْلَ\nوَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَلِيِّ الْعَظِيمِ، رَبِّ اغْفرْ لِي)).", "oromo": "“Dhugaan gabbaramaan Allaah malee hin jiru. Inni tokkicha shariika\n    hin qabneedha."}, {"arabic": "((الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لِي\nبِذِكْرِهِ)).", "oromo": "“Faaruun kan Rabbii isa qaama kiyya nagaa godhee lubbuu kiyya natti\n    deebisee isa yaadachuu naaf eeyyameeti.”"}, {"arabic": "إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَءَايَٰتٍۢ لِّأُو۟لِى ٱلْأَلْبَٰبِ\n\nٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَٰمًۭا وَقُعُودًۭا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًۭا سُبْحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ\n\nرَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ ۖ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍۢ\n\nرَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًۭا يُنَادِى لِلْإِيمَٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا ۚ رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ\n\nرَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَٰمَةِ ۗ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ\n\nفَٱسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّى لَآ أُضِيعُ عَمَلَ عَٰمِلٍۢ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ ۖ بَعْضُكُم مِّنۢ بَعْضٍۢ ۖ فَٱلَّذِينَ هَاجَرُوا۟ وَأُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأُوذُوا۟ فِى سَبِيلِى وَقَٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ثَوَابًۭا مِّنْ عِندِ ٱللَّهِ ۗ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلثَّوَابِ\n\nلَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُوا۟ فِى ٱلْبِلَٰدِ\n\nمَتَٰعٌۭ قَلِيلٌۭ ثُمَّ مَأْوَىٰهُمْ جَهَنَّمُ ۚ وَبِئْسَ ٱلْمِهَادُ\n\nلَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نُزُلًۭا مِّنْ عِندِ ٱللَّهِ ۗ وَمَا عِندَ ٱللَّهِ خَيْرٌۭ لِّلْأَبْرَارِ\n\nوَإِنَّ مِنْ أَهْلِ ٱلْكِتَٰبِ لَمَن يُؤْمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَٰشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًۭا قَلِيلًا ۗ أُو۟لَٰٓئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ ۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ\n\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ", "oromo": ""}, {"arabic": "6.  2 ــ دُعَــــاءُ لُبْسِ الثَّـــــوْبِ", "oromo": "Du’aa’ii huccuu uffachuu"}, {"arabic": "(الْحَمْدُ للَّهِ الَّذِي كَسَانِي هَذَا (الثَّوْبَ) وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا\nقُوَّة...)).", "oromo": "“Faaruun kan Rabbii huccuu kana na uffisee tooftaafi humna ana biraa\n    ta’een maleetti naaf kenneeti.”"}]}, {"num": 3, "arabicTitle": "دُعَاءُ لُبْسِ الثَّوْبِ الجَدِيدِ", "oromoTitle": "Du’aa’ii huccuu haaraa uffachuu", "duas": [{"arabic": "(اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ\nمِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ)).", "oromo": "Yaa Rabbi faaruun keeti. Situ isa na uffise. Toltuu isaatiifi toltuu\n    inni tolfameef irraan si kadha. Hamtuu isaatiifi hamtuu inni\n    tolfameef irraa sittin maganfadha."}]}, {"num": 4, "arabicTitle": "الدُّعَاءُ لِمَنْ لَبِسَ ثَوْباً جَدِيداً", "oromoTitle": "Du’aa’ii nama huccuu haaraa uffateef godhamu", "duas": [{"arabic": "((تُبْلِي وَيُخْلِفُ اللَّهُ تَعَالى)).", "oromo": "“Kun sirraa dhumee Rabbiin bakka haa buusu.”"}, {"arabic": "((اِلْبَسْ جَدِيداً وَعِشْ حَمِيداً وَمُتْ شَهِيداً)).", "oromo": "Haaraa uffadhu. Rabbiin faarsaa jiraadhu. Wareegamii du’i."}]}, {"num": 5, "arabicTitle": "مَا يَقُولُ إِذَا وَضَعَ ثـَوَبَهُ", "oromoTitle": "Waan yeroo huccuu baasan jedhamu", "duas": [{"arabic": "(بِسْمِ اللَّهِ)).", "oromo": "Maqaa Rabbiitiin"}]}, {"num": 6, "arabicTitle": "دُعَاءُ دُخُولِ الْخَلاءِ", "oromoTitle": "Du’aa’ii yeroo mana fincaanii seenanii", "duas": [{"arabic": "([بِسْمِ اللَّهِ] اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبْثِ وَالْخَبائِثِ)).", "oromo": "Maqaa Rabbiitiin; yaa Rabbi ani jaarsa jinniifi jaartii jinnii irraa\n    sittin maganfadha."}]}, {"num": 7, "arabicTitle": "دُعَاءُ الخُرُوجِ مِنَ الْخَلاء", "oromoTitle": "Du’aa’ii yeroo mana fincaaniitii bahanuu", "duas": [{"arabic": "(غُفْرَانَكَ)).", "oromo": "Araarama keen [barbaada]."}]}, {"num": 8, "arabicTitle": "الذِّكْرُ قَبْلَ الْوُضُوءِ", "oromoTitle": "Zikrii wuduu dura godhamu", "duas": [{"arabic": "(بِسْمِ اللَّهِ)).", "oromo": "Maqaa Rabbiitiin."}]}, {"num": 9, "arabicTitle": "الذِّكْرُ بعدَ الفَرَاغِ مِنَ الوُضُوءِ", "oromoTitle": "Zikrii wuduu booda godhamu", "duas": [{"arabic": "((أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ\nوَرَسُولُهُ..)).", "oromo": "“Dhugaan gabbaramaan Rabbii tokkicha hiriyaa hin qabne malee akka\n    hin jirre ragaan baha. Muhammadis gabrichaafi ergamaa Isaa ta’uu\n    ragaan baha.”"}, {"arabic": "((اللَّهُمَّ اجْعَلنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ)).", "oromo": "“Yaa Rabbi warra tawbachuu baay’isuufi qulqulleeffannaa baay’isuu irraa nu taasisi.”"}, {"arabic": "((سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ)).", "oromo": "“Subhanakal-lahumma wabihamdika ashhadu an la ilaha illa anta astaghfiruka wa-atoobu ilayk.”"}]}, {"num": 10, "arabicTitle": "الذِّكْرُ عِنْدَ الخُرُوجِ مِنَ الْمَنْزِلِ", "oromoTitle": "Zikrii yeroo manaa bahan jedhamu", "duas": [{"arabic": "((بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلاَّ بِاللَّهِ)).", "oromo": "“Maqaa Rabbiitiin. Rabbirratti hirkadhe. Tooftaafi humni Rabbiin\n    biraa malee hin argamu.”"}, {"arabic": "((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ، أَوْ أُضَلَّ، أَوْ أَزِلَّ، أَوْ أُزَلَّ، أَوْ أَظْلِمَ، أَوْ\nأُظْلَمَ، أَوْ أَجْهَلَ، أَوْ يُجْهَلَ عَلَيَّ)).", "oromo": "“Yaa Rabbi ani jallachuu yookiin jallifamuu, mucucaachuu yookiin\n    mucuceeffamuu, miidhuu yookiin miidhamuu, wallaalumaan nama miidhuu\n    yookiin miidhamuu irraa sittin maganfadha.”"}]}, {"num": 11, "arabicTitle": "الذِّكْرُ عِندَ دُخُولِ المَنْزِلِ", "oromoTitle": "Zikrii yeroo mana seenan jedhamu", "duas": [{"arabic": "(بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا، ثُمَّ لِيُسَلِّمْ\nعَلَى أَهْلِهِ)).", "oromo": "“Maqaa Rabbiitiin seennee maqaa Rabbiitiin baane. Rabbii keenya\n    irrattis hirkanneerra.” Ergasii salaamtaa jedha."}]}, {"num": 12, "arabicTitle": "دُعَاءُ الذَّهَابِ إِلَى المَسْجِدِ", "oromoTitle": "Du’aa’ii yeroo masjida deemanuu", "duas": [{"arabic": "(اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُوراً، وَفِي لِسَانِي نُوراً، وَفِي سَمْعِي نُوراً، وَفِي بَصَرِي\nنُوراً، وَمِنْ فَوْقِي نُوراً، وَمِنْ تَحْتِي نُوراً، وَعَنْ يَمِينِي نُوراً، وَعَنْ شِمَالِي نُوراً، وَمِنْ\nأَمَامِي نُوراً، وَمِنْ خَلْفِي نُوراً، وَاجْعَلْ فِي نَفْسِي نُوراً، وَأَعْظِمْ لِي نُوراً، وَعَظِّم لِي\nنُوراً، وَاجْعَلْ لِي نُوراً، وَاجْعَلْنِي نُوراً، اللَّهُمَّ أَعْطِنِي نُوراً، وَاجْعَلْ فِي عَصَبِي نُوراً،\nوَفِي لَحْمِي نُوراً، وَفِي دَمِي نُوراً، وَفِي شَعْرِي نُوراً، وَفِي بَشَرِي نُوراً)).", "oromo": "Yaa Rabbi qalbii kiyya keessa ifaa godhi. Arraba koo keessas ifaa,\n    dhageettii koo keessas ifaa, agartuu koo keessas ifaa, gubbaa kiyyas\n    ifaa, jala kootis ifaa, mirga koo irraanis ifaa, bitaa kiyya\n    irraanis ifaa, fuuldura kootis ifaa, duuba kiyyaanis ifaa, lubbuu\n    koo keessas ifaa taasisi. Ifaa guddaa naaf godhi. Ifaa naaf guddisi.\n    Ifaa naaf godhi. Ifaa na godhi. Yaa Rabbi ifaa naaf kenni. Hidda\n    kiyya keessas ifaa taasisi. Foon kiyya keessas ifaa taasisi. Dhiiga\n    kiyya keessas ifaa taasisi. Rifeensa kiyya keessas ifaa taasisi.\n    Qaama kiyya keessas ifaa taasisi.” “yaa Rabbi qabrii kiyya\n    keessatti ifaa naaf taasisi. … lafee kiyya keessas ifaa\n    taasisi.” [ifaa naaf dabali; ifaa naaf dabali; ifaa naaf\n    dabali.] “Ifaa irratti ifaa naaf kenni.”"}]}, {"num": 13, "arabicTitle": "دُعَاءُ دُخُولِ المَسْجِد", "oromoTitle": "Du’aa’ii yeroo masjida seenanuu", "duas": [{"arabic": "(يَبْدَأُ بِرِجْلِهِ اليُمْنَى))، وَيَقُولُ: ((أَعُوذُ بِاللَّهِ العَظِيمِ، وَبِوَجْهِهِ\nالكَرِيمِ، وَسُلْطَانِهِ القَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ)) [بِسْمِ اللَّهِ،\nوَالصَّلَاةُ] [وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ] ((اللَّهُمَّ افْتَحْ لِي أَبْوَابَ\nرَحْمَتِكَ)).", "oromo": "Shayxaana abaaramaa irraa Rabbii guddaatti, fuula Isaa kabajamaafi\n    taayitaa Isaa turaa ta’ettin maganfadha.” “Maqaa Rabbiitiin;\n    rahmataafi nageenyi Ergamaa Rabbii irra haa jiraatu.  Yaa Rabbi\n    hulaa rahmata keetii naaf bani.”"}]}, {"num": 14, "arabicTitle": "دُعَاءُ الخُرُوجِ مِنَ المَسْجِد", "oromoTitle": "Du’aa’ii yeroo masjidaa bahanuu", "duas": [{"arabic": "(يَبْدَأُ بِرِجْلِهِ الْيُسْرَى)) وَيَقُولُ: ((بِسْمِ اللَّهِ وَالصّلَاةُ وَالسَّلَامُ عَلَى\nرَسُولِ اللَّهِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِك، اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ\nالرَّجِيمِ)).", "oromo": "“Maqaa Rabbiitiin; rahmataafi nageenyi ergamaa Rabbii irra haa\n    jiraatu. Yaa Rabbi ani tola kee irraan si kadha. Yaa Rabbi shayxaana\n    abaaramaa irraa na tiksi.”"}]}, {"num": 15, "arabicTitle": "أَذكَارُ الأَذَانِ", "oromoTitle": "Zikrii yeroo azaanaa godhamu", "duas": [{"arabic": "يَقُولُ مِثْلَ مَا يَقُولُ المُؤَذِّنُ إِلاَّ فِي ((حَيَّ عَلَى الصَّلَاةِ وَحَيَّ عَلَى الْفَلَاحِ)) فَيقُولُ: ((لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)).\n\nيَقُولُ: ((وَأَنَا أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَنَّ مُحَمَّداً\nعَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللَّهِ رَبَّاً، وَبِمُحَمَّدٍ رَسُولاً، وَبِالْإِسْلاَمِ دِينَاً)) ((يَقُولُ\nذَلِكَ عَقِبَ تَشَهُّدِ الْمُؤَذِّنِ)).\n\n((يُصَلِّي عَلَى النَّبِيِّ صلي الله عليه وسلم بَعْدَ فَرَاغِهِ مِنْ إِجَابَةِ\nالْمُؤَذِّنِ)).\n\nيَقُولُ: ((اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلاَةِ الْقَائِمَةِ، آتِ مُحَمَّداً\nالوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامَاً مَحمُوداً الَّذِي وَعَدْتَهُ، [إِنَّكَ لَا تُخْلِفُ\nالْمِيعَادَ])).\n\n((يَدْعُو لِنَفسِهِ بَيْنَ الْأَذَانِ وَالإِقَامَةِ فَإِنَّ الدُّعَاءَ حِينَئِذٍ لاَ\n    يُرَدُّ)).", "oromo": "Fakkii waan mu’azzinni jedhuu jedha. Garuu “hayya alassalaafi hayya\n    alal falaah” irratti qofa “tooftaafi humni Rabbiin biraa malee hin\n    argamu” jedha.\n\nNi jedha: “anis akka dhugaan gabbaramaan Rabbii tokkicha hiriyaa hin\n    qabne malee hin jirreefi muhammadis gabricha Rabbiifi ergamaa Isaa\n    ta’uu ragaan baha. Allaahn gabbaramaa keenya ta’uu, Muhammad ergamaa\n    ta’uufi Islaamni amantii kiyya ta’uu jaaladheera.” Kan inni kana\n    jedhu yeroo mu’azzinni shahaadaa lamaan jedhee xumure.\n\nBooda haala kanaan azaana jawaabee xumuree Nabiyyii (saw) irratti\n    salawaata buusa.\n\nSana booda ni jedha: “yaa Rabbii waamicha guutuu kanaafi salaata\n    dhaabamaartuu! Muhammadiif wasiilaafi kabajaa kenne. Sadarkaa\n    kabajamaa isaaf waadaa seente irrattis isa kaasi. [Ati waadaa hin\n    faallessitu waan ta’eef]”\n\nAzaanaafi iqaamaa jidduu du’aa’ii godha. Du’aa’iin yeroo kanaa hin\n    didamu waan ta’eef."}]}, {"num": 16, "arabicTitle": "دُعَـــــاءُ الاسْـــــتِفْتَاحِ", "oromoTitle": "Du’aa’ii salaanni ittiin banamu", "duas": [{"arabic": "((اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ\nنَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْني مِنْ خَطَايَايَ،\nبِالثَّلْجِ وَالْماءِ وَالْبَرَدِ)).", "oromo": "“'Yaa Rabbi! Akka jidduu bahaafi lixaa wal irraa fageessite jidduu\n    kootiifi jidduu dilii kootii wal irraa fageessi (cubbuu irraa na\n    fageessi). Yaa Rabbi! Akka uffanni adiin xurii irraa qulqullaahutti\n    anas dilii koo irraa na qulqulleessi. Yaa Rabbi! dilii koo irraa\n    cabbii, bishaaniifi cabbiidhaan na dhiqi.”"}, {"arabic": "((سُبْحانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبارَكَ اسْمُكَ،وَتَعَالَى جَدُّكَ،وَلاَ إِلَهَ\nغَيْرُكَ)).", "oromo": "“Yaa Rabbi faaruu keetii wajjinin si qulqulleessa; maqaan kee bu'aan\n    isaa baay'ate, ulfinni keetis olta’e, si malee dhugaan gabbaramaan\n    biraa hin jiru.”"}, {"arabic": "((وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالأَرْضَ حَنِيفَاً وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ\nصَلاَتِي، وَنُسُكِي، وَمَحْيَايَ، وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لاَ شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا\nمِنَ الْمُسْلِمِينَ. اللَّهُمَّ أَنْتَ المَلِكُ لاَ إِلَهَ إِلاَّ أَنْتَ، أَنْتَ رَبِّي وَأَنَا عَبْدُكَ، ظَلَمْتُ\nنَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبي جَمِيعَاً إِنَّهُ لاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ.\nوَاهْدِنِي لِأَحْسَنِ الأَخْلاقِ لَا يَهْدِي لِأَحْسَنِها إِلاَّ أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا، لاَ يَصْرِفُ\nعَنِّي سَيِّئَهَا إِلاَّ أَنْتَ، لَبَّيْكَ وَسَعْدَيْكَ، وَالخَيْرُ كُلُّهُ بِيَـــــدَيْكَ، وَالشَّرُّ لَيْسَ\nإِلَيْـــــــــــكَ،\nأَنَـا بِكَ وَإِلَيْكَ، تَبارَكْتَ وَتَعَالَيْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ)).", "oromo": "“Ani haalan gara tawhiidaa dabee jiruun fuula kiyya gara Isa samiifi\n    dachii uumeetti deebiseera. Salaanni kiyya, ibaadaan kiyya, jiruun\n    kiyyaafi duuti kiyya Rabbii gooftaa aalamaatiifi. Shariikni isaaf\n    hin jiru. Kanattin ajajames. Ani Muslima irraayi. Yaa Rabbi mootiin\n    suma qofa; dhugaan gabbaramaan si malee hin jiru. Ati Gooftaa kiyya\n    ani gabricha keeti. Lubbuu kiyya miidheera. Yakka kiyyas amaneera.\n    Dilii koo hundaa naaf araarami. Kan dilii araaramu si malee waan hin\n    jirreef. Yaa Rabbi gara amala gaariitti na qajeelchi. Gara akkaan\n    gaarii isheetti si malee kan qajeelchu hin jiru. Hamtuu ishee immoo\n    narraa deebisi; hamtuu ishee si malee kan narraa deebisu waan hin\n    jirreef. Owwaadhe. Milkuunis kan keeti. Toltuun hunduu sirka jira.\n    Hamtuun gara keetii miti. Ani siinin jira gara keettin deebi’a.\n    Guddattee ol taate. Araaraman sirra barbaada; gara keettin\n    deebi’a.”"}, {"arabic": "((اللَّهُمَّ رَبَّ جِبْرَائِيلَ، وَمِيْكَائِيلَ، وَإِسْرَافِيلَ، فاطِرَ السَّمَوَاتِ وَالأَرْضِ، عَالِمَ\nالغَـــيْبِ وَالشَّــــهَادَةِ أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ. اهْدِنِي\nلِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقيمٍ)).", "oromo": "“Yaa Allaah gooftaa Jibriil, Mikaa’eeliifi Israafiil! Uumaa samiifi\n    dachii! Beekaa fagoofi dhihoo kan taate! Ati waan gabroonni kee\n    irratti wal dhabaa turan keessatti murtii kennita. Haqa waan\n    keessatti wal dhabameef na qajeelchi. Ati abbaa feete karaa\n    sirriitti qajeelchita waan taateef.”"}, {"arabic": "((اللَّهُ أَكْبَرُ كَبِيرَاً، اللَّهُ أَكْبَرُ كَبِيراً، اللَّهُ أَكْبَرُ كَبِيراً، وَالْحَمْدُ لِلَّهِ\nكَثيراً، وَالْحَمْدُ لِلَّهِ كَثيراً، وَالْحَمْدُ لِلَّهِ كَثيراً، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلاً))\nثَلاثاً ((أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ: مِنْ نَفْخِهِ، وَنَفْثِهِ، وَهَمْزِهِ)).", "oromo": "“Rabbiin guddate guddina ol aanaa (x3). Faaruun kan Rabbiiti;\n    faaruun baay’een (x3). Ganamaafi galgala qulqullina isaan malun Isa\n    qulqulleessa.” Kana hundaa si’a sadii jedha. Achiin “shayxaana irraa\n    Rabbittin maganfadha: boona isaa irraa, walaloo isaafi isa inni nama\n    kuffisu irraa.”"}, {"arabic": "((اللَّهُمَّ لَكَ الْحَمْدُ، أَنْتَ نُورُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ\nالْحَمْدُ أَنْتَ قَيِّمُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ، [وَلَكَ الْحَمْدُ أَنْتَ رَبُّ السَّمَواتِ وَالأَرْضِ\nوَمَنْ فِيهِنَّ] [وَلَكَ الْحَمْدُ لَكَ مُلْكُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ] [وَلَكَ الْحَمْدُ أَنْتَ مَلِكُ\nالسَّمَوَاتِ وَالأَرْضِ] [وَلَكَ الْحَمْدُ] [أَنْتَ الْحَقُّ، وَوَعْدُكَ الْحَقُّ، وَقَوْلُكَ الْحَقُّ، وَلِقاؤُكَ\nالْحَقُّ، وَالْجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالنَّبِيُّونَ حَقٌّ، وَمحَمَّدٌ حَقٌّ، وَالسّاعَةُ حَقٌّ] [اللَّهُمَّ لَكَ\nأَسْلَمتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَبِكَ آمَنْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خاصَمْتُ، وَإِلَيْكَ حاكَمْتُ. فَاغْفِرْ\nلِي مَا قَدَّمْتُ، وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ، وَمَا أَعْلَنْتُ] [وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي] [أَنْتَ\nالمُقَدِّمُ، وَأَنْتَ المُؤَخِّرُ لاَ إِلَهَ إِلاَّ أَنْتَ] [أَنْتَ إِلَهِي لاَ إِلَهَ إِلاَّ أَنْتَ] [وَلاَ حَوْلَ\nوَلاَ قُوَّةَ إِلاَّ بِاللَّهِ])).", "oromo": "“Yaa Rabbi faaruun kan keeti ati ifaa samii, dachiifi warra isaan\n    keessa jiraniiti. Ammas faaruun kan keeti ati jiraachisaa samii,\n    dachiifi warra isaan keessa jiraniiti. Ammas faaruun kan keeti ati\n    Gooftaa samii, dachiifi warra isaan keessa jiraniiti. Ammas faaruun\n    kan keeti mootummaan samii, dachiifi warra isaan keessa jiranii\n    keeti. Ati mootii samiifi dachiiti faaruun keeti. Ammas faaruun\n    keeti. Ati dhugaadha. Baallamni keetis dhugaadha. Jechi keetis\n    dhugaadha. Qunnamtiin keetis dhugaadha. Jannannis dhugaadha. Ibiddis\n    dhugaadha. Nabiyyoonnis dhugaadha. Muhammadis (saw) dhugaadha.\n    Qiyaamaanis dhugaadha. Yaa Rabbi siif ajajameera. Sirratti\n    hirkadheeras. Sittis amane. Gara keettis deebi’e. Maqaa keetiin\n    falme. Murtiis gara keetti barbaade. Waan ani dabarse, waan ani\n    booda aanses, waan ani iccitii godheefi mullises naaf araarami. Ati\n    dura buufta booda aansitas waan ta’eef. Dhugaan gabbaramaan si malee\n    hin jiru. Ati gooftaa kootii dhugaan gabbaramaan si malee hin\n    jiru.”"}]}, {"num": 17, "arabicTitle": "دُعَــــاءُ الرُّكُــــوعِ", "oromoTitle": "Du’aa’ii rukuu’aa", "duas": [{"arabic": "((سُبْحانَ رَبِّيَ الْعَظِيمِ)). ثلاث مرَّاتٍ.", "oromo": "“Rabbiin kiyya guddaan qulqullaa’e.” (x3)"}, {"arabic": "((سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي)).", "oromo": "“Yaa Rabbi faaruu keetii waliinin si qulqulleessa. Yaa Rabbi naaf\n    araarami.”"}, {"arabic": "((سُبُّوُحٌ، قُدُّوسٌ، رَبُّ المَلاَئِكَةِ وَالرُّوحِ)).", "oromo": "“[Rabbiin] shariika irraa qulqulleeffamaa, hanqina irraa\n    qulqulleeffamaa, Rabbii Jibriiliifi maleykotaati.”"}, {"arabic": "((اللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي، وَبَصَــــــــرِي،\nوَمُخِّي، وَعَظْمِي، وَعَصَبِي، [وَمَا استَقَلَّتْ بِهِ قَدَمِي])).", "oromo": "“Yaa Rabbi siif rukuu’a godhe; sittis amane. Siif ajajameeras.\n    Dhageettiin, agartuun, dhukti, lafeen, hiddiifi wanti miilli kiyya\n    ittiin dhaabbate siif xinnaateera.”"}, {"arabic": "((سُبْحَانَ ذِي الْجَبَرُوتِ، وَالْمَلَكُوتِ، وَالْكِبْرِيَاءِ، وَالْعَظَمَةِ)).", "oromo": "“Rabbiin abbaan humnaa, mootummaa, guddinaafi ol ta’iinsaa\n    qulqullaa’e.”"}]}, {"num": 18, "arabicTitle": "دُعَاءُ الرَّفْعِ مِنَ الرُّكُوعِ", "oromoTitle": "Du’aa’ii yeroo rukuu’a irraa ka’anuu", "duas": [{"arabic": "((سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ)).", "oromo": "“Rabbiin Nama Isa faarseef dhaga’e.”"}, {"arabic": "((رَبَّنَا وَلَكَ الْحَمْدُ، حَمْداً كَثيراً طَيِّباً مُبارَكاً فِيهِ)).", "oromo": "“Rabbii keenya faaruun keeti. Faaruu baay’ee, gaarii, barakaan ishee\n    keessa jirun [si faarsa].”"}, {"arabic": "((مِلْءَ السَّمَوَاتِ وَمِلْءَ الأَرْضِ، وَمَا بَيْنَهُمَا، وَمِلْءَ مَا شِئْتَ مِنْ شَيءٍ بَعْدُ. أَهلَ\nالثَّناءِ وَالْمَجْدِ، أَحَقُّ مَا قَالَ الْعَبْدُ، وَكُلُّنَا لَكَ عَبْدٌ. اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ،\nوَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الجَدِّ مِنْكَ الجَدُّ)).", "oromo": "“Guutuu samii, guutuu dachiifi waan jidduu isaan lamaanii jiranuun\n    [si faarsa]. Guutuu waan ati feete waan kanaan ala jiruu. [Ati]\n    abbaa faaruufi guddinaati. Akkaan dhugaan wanti gabrichi kee\n    dubbatee, nuti hunduu siif gabrichaa, ‘yaa Rabbi waan ati kennite\n    wanti dhorgatu hin jiru; waan ati dhorgattes kennaan hin jiru. Abbaa\n    qabeenyaa adabbii kee irraa qabeenyi isaa homaa hin fayyadu.”"}]}, {"num": 19, "arabicTitle": "دُعَــــاءُ السُّجُـــــودِ", "oromoTitle": "Du’aa’ii sujuudii", "duas": [{"arabic": "((سُبْحَانَ رَبِّيَ الأَعْلَى)) ثلاث مرَّاتٍ.", "oromo": "“Rabbiin kiyya ol ta’aan qulqullaa’e.” Si’a sadii"}, {"arabic": "((سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي)) .", "oromo": "“Yaa Rabbi faaruu keetii waliinin si qulqulleessa. Yaa Rabbi naaf\n    araarami.”"}, {"arabic": "((سُبوحٌ، قُدُّوسٌ، رَبُّ المَلَائِكَةِ وَالرُّوحِ)) .", "oromo": "“[Rabbiin] shariika irraa qulqulleeffamaa, hanqina irraa\n    qulqulleeffamaa, Rabbii Jibriiliifi maleykotaati.”"}, {"arabic": "((اللَّهُمَّ لَكَ سَجَدْتُ وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ،\n    وَصَوَّرَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسنُ الْخَالِقينَ)).", "oromo": "“Yaa Rabbi siif sujuude. Sitti amanes. Siif ajajame. Fuulli kiyya\n    kan isa uumee, isa bocee, dhageettiifi agartuu isaaf godheef\n    sujuudeera. Rabbiin akkaan gaaromsee uumaa ta’e toltuun isaa\n    baay’ateera.”"}, {"arabic": "((سُبْحَانَ ذِي الْجَبَرُوتِ، وَالْمَلَكُوتِ، وَالْكِبْرِيَاءِ، وَالْعَظَمَةِ)) .", "oromo": "“Rabbiin abbaan humnaa, mootummaa, guddinaafi ol ta’iinsaa\n    qulqullaa’e.”"}, {"arabic": "((اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ: دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلاَنِيَّتَهُ\nوَسِرَّهُ)).", "oromo": "“Yaa Rabbi yakka kiyya hunda, xiqqoofi guddaa isaa, jalqabaafi dhuma\n    isaa, mullataafi dhokataa isaa naaf araarami.”"}, {"arabic": "((اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقوبَتِكَ، وَأَعُوذُ بِكَ\nمِنْكَ، لاَ أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ)).", "oromo": "“Yaa Rabbi dallansuu kee irraa jaalala keetti, adabbii kee irraa\n    nageenya keettin maganfadha. Sirraa sumattin maganfadha. Faaruu\n    sirratti godhamu lakkaa’ee hin xumuru. Ati akkuma lubbuu kee\n    faarsiteedha.”"}]}, {"num": 20, "arabicTitle": "دُعَاءُ الجلْسَةِ بَيْنَ السَّجْدَتَيْنِ", "oromoTitle": "Du’aa’ii jidduu sujuuda lamaanii", "duas": [{"arabic": "((رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي)).", "oromo": "“Yaa Rabbi naaf araarami! Yaa Rabbi naaf araarami.”"}, {"arabic": "((اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَاجْبُرْنِي، وَعَافِنِي، وَارْزُقْنِي،", "oromo": "“Yaa Rabbi naaf araarami. Na mararfadhu. Na qajeelchi. Na suphi.\n    Nagaa na godhi. Na soori. Ol na kaasi.”"}]}, {"num": 21, "arabicTitle": "دُعَاءُ سُجُودِ التِّلاَوَةِ", "oromoTitle": "Du’aa’ii sujuudii yeroo Qur'aanni qara’amuu", "duas": [{"arabic": "((سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ، ﴿فَتَبارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ﴾)).", "oromo": "“Fuulli kiyya kan tooftaafi humna Isaatiin isa uume, isa boce,\n    dhageettiifi agartuu isaaf godheef sujuudeera. Rabbiin akkaan\n    gaaromsee uumaa ta’e toltuun isaa baay’ateera.”"}, {"arabic": "((اللَّهُمَّ اكْتُبْ لِي بِهَا عِنْدَكَ أَجْراً، وَضَعْ عَنِّي بِهَا وِزْراً، وَاجْعَلْهَا لِي عِنْدَكَ\nذُخْراً، وَتَقَبَّلْهَا مِنِّي كَمَا تَقَبَّلْتَهَا مِنْ عَبْدِكَ دَاوُدَ)).", "oromo": "“Yaa Rabbi Si biratti mindaa ittiin naaf barreessi. Isheedhaan badii\n    narraa harcaasi. Isheedhaan si biratti kuusaa naaf godhi. Akka\n    gabricha kee Daawud irraa qeebalte narraa qeebali.”"}]}, {"num": 22, "arabicTitle": "التَّشَـــــــــــهُّدُ", "oromoTitle": "Tashahhuda", "duas": [{"arabic": "(التَّحِيَّاتُ لِلَّهِ، وَالصَّلَواتُ، وَالطَّيِّباتُ، السَّلاَمُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ\nوَبَرَكَاتُهُ، السَّلاَمُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ. أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ\nوَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسولُهُ)).", "oromo": "“Kabajaan, salaatonni (ibaadaan adda addaa) fi dubbiin gaggaariin\n    hunduu kan Rabbiiti. Yaa Nabiyyichaa! Nageenyi sirra haa jiraatu;\n    Rahmanni Rabbiitiifi barakaan isaas. Nageenyi nuufi gabroottan\n    Rabbii gaggaarii irra haa jiraatu. 'Dhugaan gabbaramaan Rabbiin\n    malee hin jiruu' ragaan ba'a. Muhammadis gabricha Rabbiifi ergamaa\n    isaa ta'uu ragaan ba'a.”"}]}, {"num": 23, "arabicTitle": "الصَّلاةُ عَلَى النَّبيِّ ص بَعْدَ التَّشَهُّدِ", "oromoTitle": "Tashahhuda booda Nabiyyii (saw) irratti salawaata buusuu", "duas": [{"arabic": "((اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيتَ عَلَى إِبْرَاهِيمَ، وَعَلَى آلِ\nإِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى\nإِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ)).", "oromo": "\"Yaa Rabbi akkuma Ibraahiimiifi maatii Ibraahiim irratti Rahmata\n    buufte Muhammadiifi Maatii Muhammad irratti Rahmata buusi; Ati\n    faarfamaa guddaa waan taateef. Ammas akkuma Ibraahiimiifi maatii\n    Ibraahiim irratti barakaa buufte Muhammadiifi Maatii Muhammad\n    irratti barakaa buusi; Ati faarfamaa guddaa waan taateef.”"}, {"arabic": "((اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى أَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ.\nوَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى أَزْواجِهِ وَذُرِّيَّتِهِ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ. إِنَّكَ حَمِيدٌ\nمَجِيدٌ)).", "oromo": "\"Yaa Rabbi akkuma maatii Ibraahiim irratti Rahmata buufte Muhammad,\n    niitolii isaaniitiifi ilmaan isaanii irratti Rahmata buusi. Ammas\n    akkuma maatii Ibraahim irratti barakaa buufte Muhammad, niitolee\n    isaaniifi ilmaan isaanii irratti barakaa buusi. Ati faarfamaa guddaa\n    waan taateef.”"}]}, {"num": 24, "arabicTitle": "الدُّعَاءُ بَعْدَ التَّشَهُّدِ الأَخِيرِ قَبْلَ السَّلاَمِ", "oromoTitle": "Du’aa’ii tashahhuda boodaa keessatti salaamtaa dura godhamu", "duas": [{"arabic": "((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ جَهَنَّمَ، وَمِنْ فِتْنَةِ الْمَحْيَا\nوَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ)).", "oromo": "“Yaa Rabbi ani adabbii qabriifi adabbii jahannamaa irraa sittin\n    maganfadha. Mokkoroo jireenyaafi du’aa irraa, akkasumas mokkoroo\n    Masiih Addajjaal irraa sittin maganfadha.”"}, {"arabic": "((اللَّهُمَّ إِنِّي أَعوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ\nالدَّجَّالِ، وَأَعوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ. اللَّهُمَّ إِنِّي أَعوذُ بِكَ مِنَ الْمَأْثَمِ\nوَالْمَغْرَمِ)).", "oromo": "“Yaa Rabbi ani adabbii qabrii irraa sittin maganfadha. Mokkoroo\n    Masiih Addajjaal irraas sittin maganfadha. Mokkoroo jireenyaafi\n    du’aa irraas sittin maganfadha. Yaa Rabbi ani yakkaafi hidaan\n    qabamuu irraa sittin maganfadha.”"}, {"arabic": "((اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْماً كَثِيراً، وَلاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ، فَاغْفِرْ\nلِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي، إِنَّكَ أَنْتَ الغَفورُ الرَّحيمُ)).", "oromo": "“Yaa Rabbi! Ani miidhaa baay'ee lubbuu koo miidheera; si malee kan\n    dilii araaramu hin jiru. Kanaafuu, araarama si biraa ta'e naaf\n    araarami. Ati araaramaa mararfataa waan taateef.\""}, {"arabic": "((اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ، وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ، وَمَا أَعْلَنْتُ، وَمَا\nأَسْرَفْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي. أَنْتَ الْمُقَدِّمُ، وَأَنْتَ الْمُؤَخِّرُ لاَ إِلَهَ إِلاَّ\nأَنْتَ)).", "oromo": "“Yaa Rabbi waan ani hojjadhee dabarseefi booda aanse, waan ani\n    iccitiifi mullisee hojjadhe, waan ani daangaa tareefi waan ati qofti\n    narraa beektu naaf araarami. Situ dura buusa; sumatu booda aansas.\n    Dhugaan gabbaramaan si malee hin jiru.”"}, {"arabic": "((اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ، وَشُكْرِكَ، وَحُسْنِ عِبادَتِكَ))", "oromo": "“Yaa Rabbi si yaadachuu, si galateeffachuufi ibaadaa kee gaaromsuu\n    keessatti na gargaari.”"}, {"arabic": "((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُخْلِ، وَأَعوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ مِنْ أَنْ\nأُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا وَعَذَابِ الْقَبْرِ)).", "oromo": "“Yaa Rabbi ani doynummaa irraa sittin maganfadha. Lunnummaa irraas\n    sittin maganfadha. Umurii isa gadi kufaatti deebifamuu irraas sittin\n    maganfadha. Mokkoroo addunyaafi adabbii qabrii irraas sittin\n    maganfadha.”"}, {"arabic": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ)).", "oromo": "“Yaa Rabbi ani jannata si kadheen ibidda irraa sitti\n    maganfadha.”"}, {"arabic": "((اللَّهُمَّ بِعِلْمِكَ الغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْراً\nلِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْراً لِي، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ\nوَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْغِنَى\nوَالْفَقْرِ، وَأَسْأَلُكَ نَعِيماً لاَ يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لاَ تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَا بَعْدَ\nالْقَضَاءِ، وَأَسْــــأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ،\nوَالشَّوْقَ إِلَى لِقائِكَ فِي غَيرِ ضَرَّاءَ مُضِرَّةٍ، وَلاَ فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَا بِزِينَةِ\nالإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ)).", "oromo": "“Yaa Rabbi beekumsa kee fagootiifi dandeettii kee uumama irratti\n    qabduun waan jireenyi anaaf gaarii ta’uu beektuun na jiraachisii\n    yeroo duuti anaaf gaarii ta’uu beektutti na ajjeesi. Yaa Rabbi ani\n    fagoofi dhihootti si sodaachuun si kadha. Yeroo jaalalaafi\n    dallansuus haqa dubbachuun si kadha. Durummaafi hiyyummaa keessattis\n    giddu gala ta’uun si kadha. Qananii hin dhumnes sin kadha. Gammachuu\n    ijaa kan hin cinnes sin kadha. Murtii booda jaalalan si kadha. Du’a\n    booda jireenya gaariin si kadha. Gara fuula keetii ilaaluu\n    mi’eeffachuufi, rakkoon na miidhuufi mokkoroon na jallisu dhibamuu\n    waliin [du’ee] si qunnamuuf hawwuun si kadha. Yaa Rabbi faaya\n    iimaanaatiin nu bareechii qajeeloo qajeelchoo nu taasisi.”"}, {"arabic": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ يَا أَللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ\nيولَدْ، وَلَمْ يَكنْ لَهُ كُفُواً أَحَدٌ، أَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّكَ أَنْتَ الْغَفُورُ\nالرَّحِّيمُ)).", "oromo": "“Yaa Allaah ani ‘Ati tokkicha hirkoo hundaa, kan hin dhalleefi hin\n    dhalanne, wanti tokkollee fakkaataa Isaaf hin taane’ ta’uu keetiinin\n    yakka kiyya cufa naaf araaramuu si kadha. Situ araaramaa\n    mararfataadha waan taateef.”"}, {"arabic": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ لاَ إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لَكَ،\nالْمَنَّانُ، يَا بَدِيعَ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلاَلِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّومُ إِنِّي\nأَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ)).", "oromo": "“Yaa Rabbi ani “faaruun kan kee ta’uudhaan, dhugaan gabbaramaan si\n    malee hin jiru ati tokkicha hiriyaa hin qabne, tola oolaa ta’uu\n    keetiin’ yaa Rabbii uumaa samiifi dachii! Abbaa guddinaafi kabajaa!\n    Yaa jiraataa waan hunda to’ataa! Ani jannatan si kadha ibidda irraa\n    sittin maganfadha.”"}, {"arabic": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّي أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لاَ إِلَهَ إِلاَّ أَنْتَ الْأَحَدُ\nالصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُواً أَحَدٌ)) .", "oromo": "“Yaa Rabbi ani ‘Ati Allaah dhugaan gabbaramaan si malee hin jirre,\n    ati tokkicha hirkoo waa hundaa kan hin dhalleefi hin dhalanne, wanti\n    tokkollee isaaf fakkaataa hin taane ragaa bahuudhaanin’ si\n    kadha.”"}]}, {"num": 25, "arabicTitle": "الأَذْكَارُ بَعْدَ السَّلاَمِ مِنَ الصَّــلاَةِ", "oromoTitle": "Zikrii yeroo salaata irraa salaamtaa bahanii", "duas": [{"arabic": "((أَسْتَغْفِرُ اللَّهَ (ثَلاَثَاً) اللَّهُمَّ أَنْتَ السَّلاَمُ، وَمِنْكَ السَّلاَمُ، تَبَارَكْتَ يَا ذَا\nالْجَلاَلِ وَالْإِكْرَامِ)).", "oromo": "“Yaa Allaah naaf araarami” si’a sadii jedha. Ergasii “yaa Rabbi situ\n    nagaadha. Nageenyi si biraa argamas. Yaa abbaa guddinaafi kabajaa\n    khayriin kee baay’ateera.”"}, {"arabic": "((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ\nشَيْءٍ قَدِيرٌ [ثلاثاً]، اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ\nذَا الْجَدِّ مِنْكَ الجَدُّ)).", "oromo": "“Dhugaan gabbaramaan Rabbiin malee hin jiru. Inni tokkicha hiriyaa\n    hin qabneedha. Mootummaan kan isaati. Faaruunis kan Isaati. Inni\n    waan hundaa danda’aadha. Yaa Rabbi waan ati kennite dhorgataan hin\n    jiru. Waan ati dhorgatte immoo kennaan hin jiru. Abbaa qabeenyaa\n    adabbii kee irraa qabeenyi isaa hin fayyadu.”"}, {"arabic": "((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمدُ، وَهُوَ عَلَى\nكُلِّ شَيْءٍ قَدِيرٌ. لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ، وَلاَ نَعْبُدُ إِلاَّ\nإِيَّاهُ, لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ، لاَ إِلَهَ إِلاَّ اللَّهُ مُخْلِصِينَ لَهُ\nالدِّينَ وَلَوْ كَرِهَ الكَافِرُونَ)).", "oromo": "“Dhugaan gabbaramaan Rabbiin malee hin jiru. Inni tokkicha hiriyaa\n    hin qabneedha. Mootummaan kan isaati. Faaruunis kan Isaati. Inni\n    waan hunda irratti danda’aadha. Tooftaafi humni Rabbiin biraa malee\n    hin argamu. Dhugaan gabbaramaan Allaah malee hin jiru. Isa malee hin\n    gabbarru. Qananiin kan isaati. Tollis kan Isaati. Faaruun gaariinis\n    kan isaati. Dhugaan gabbaramaan Isa malee hin jiru. Odoma\n    kaafiroonni jibbanuu keessaan qulqulleessaa [kana ragaa\n    baana].”"}, {"arabic": "((سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَاللَّهُ أَكْبَرُ (ثلاثاً وثلاثين) لاَ إِلَهَ إِلاَّ\nاللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)).", "oromo": "“Rabbiin qulqullina [isaan malu qulqullaa’e]; Faaruun kan Rabbiiti.\n    Rabbiin waan hundarra guddate.” Si’a soddomii sadii jedha. “Dhugaan\n    gabbaramaan Rabbiin malee hin jiru. Inni tokkicha hiriyaa hin\n    qabneedha. Mootummaan kan isaati. Faaruunis kan Isaati. Inni waan\n    hundaa danda’aadha.”"}, {"arabic": "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\n\nقُلْ هُوَ ٱللَّهُ أَحَدٌ\n\nٱللَّهُ ٱلصَّمَدُ\n\nلَمْ يَلِدْ وَلَمْ يُولَدْ\n\nوَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ\n\nبِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\n\nقُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ\n\nمِن شَرِّ مَا خَلَقَ\n\nوَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ\n\nوَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ\n\nوَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ\n\nبِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\n\nقُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ\n\nمَلِكِ ٱلنَّاسِ\n\nإِلَٰهِ ٱلنَّاسِ\n\nمِنْ شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ\n\nٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ\n\nمِنَ ٱلْجِنَّةِ وَٱلنَّاسِ", "oromo": "Maqaa Rabbii Akkaan Mararfataa Akkaan Rahmata Godhaa Ta’eetiin. Jedhi: “Inni Allaah (gabbaramaa dhugaa) tokkicha. Allaahn\n    hirkoo waa hundaati. Hin dhalle hin dhalannes. Wanti tokkollee\n    fakkaataa Isaaf hin taane.”\n\nMaqaa Rabbii Akkaan Mararfataa Akkaan Rahmata Godhaa Ta’eetiin. Jedhi: “Gooftaa bariittin maganfadha. Hamtuu waan Inni\n    uumee irraa, hamtuu dukkanaa yeroo dukkanaa’e irraas, hamtuu\n    guduunfaa keessatti tuftu irraas, hamtuu haasidii yeroo inni\n    hassadu (waanyu) irraas, Rabbittin maganfadha.”\n\nMaqaa Rabbii Akkaan Mararfataa Akkaan Rahmata Godhaa Ta’eetiin. Jedhi: “Gooftaa namaattin maganfadha. Mootii namaatti,\n    Gabbaramaa namaatti, hamtuu waswaasii dhokatuufi mul’atuu irraa,\n    isa qoma namaa keessa waswaasu irraa, jinniifi nama irraa kan\n    ta’e irraan maganfadha.” Suuraalee sadan kana (Ikhlaas, Falaq,\n    Naas) salaata hunda booda dubbifama."}, {"arabic": "اللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ\nلَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ\nيَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ\nوَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ", "oromo": "“Rabbiin Isa malee haqaan gabbaramaan hin jiru. Inni jiraataadha;\n    waan hundaan dhaabbataadha. Mugaatiis ta’ee hirribni Isa hin qabatu.\n    Wanti samii keessa jiruufi wanti dachii keessa jiru hundi kan\n    Isaati. Inni hayyama Isaatiin ala Isa biratti araarsu eenyuma? Waan\n    fuuldura isaaniitiifi waan duuba isaaniis ni beeka. Beekumsa Isaa\n    irraas waan Inni fedhetti malee hin marsanu. Kursiin Isaa samiifi\n    dachii irra bal’ateera. Isaan lamaan tiksuun Isa hin dadhabsiisu.\n    Inni ol ta’aa, guddaadha.” Salaata hunda booda jedhama."}, {"arabic": "((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ\nوَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)) عَشْرَ مَرّاتٍ بَعْدَ صَلاةِ", "oromo": "“Dhugaan gabbaramaan Rabbiin malee hin jiru. Inni tokkicha hiriyaa\n    hin qabneedha. Mootummaan kan Isaati. Faaruunis kan Isaati. Ni\n    jiraachisa ni ajjeesas. Inni waan hunda irratti danda’aadha.” Booda\n    salaata Maghribaafi Subhii si’a kudhan jedhama."}, {"arabic": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نافِعاً، وَرِزْقاً طَيِّباً، وَعَمَلاً مُتَقَبَّلاً)) بَعْدَ\nالسّلامِ مِنْ صَلاَةِ الفَجْرِ.", "oromo": "“Yaa Rabbi ani beekumsa fayyadu, soorata gaariifi hojii qeebalamaan\n    si kadha.” Booda salaata Maghribaa irraa salaamtaa bahee jedha."}]}, {"num": 26, "arabicTitle": "دُعَاءُ صَلاَةِ الاسْتِخَارَةِ", "oromoTitle": "Du’aa’ii salaata Istikhaaraa[170]", "duas": [{"arabic": "قَالَ جَابرُ بْنُ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: كَانَ رسُولُ اللَّهِ × يُعَلِّمُنَا\nالاسْتِخَارَةَ فِي الْأُمُورِ كُلِّهَا كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ، يَقُولُ: ((إِذَا هَمَّ\nأَحَدُكُمْ بِالْأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ، ثُمَّ لْيَقُلْ: اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ\nبِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ العَظِيمِ؛ فَإِنَّكَ تَقْدِرُ وَلاَ أَقْدِرُ، وَتَعْلَمُ\nوَلاَ أَعْلَمُ، وَأَنْتَ عَلاَّمُ الغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأمْرَ - وَيُسَمِّي\nحَاجَتَهُ - خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي – أَوْ قَالَ: عَاجِلِهِ وَآجِلِهِ - فَاقْدُرْهُ\nلِي وَيَسِّرْهُ لِي ثمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي\nوَمَعَاشِي وَعَاقِبَةِ أَمْرِي – أَوْ قَالَ: عَاجِلِهِ وَآجِلِهِ – فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ وَاقْدُرْ\nلِيَ الْخَيْرَ حَيْثُ كَانَ، ثُمَّ أَرْضِنِي بِهِ)).", "oromo": "Jaabir bin Abdullaah (ra) ni jedhe: Ergamaan Rabbii (saw) akka\n    suuraa Qur'aanaa nu barsiisanutti waan hunda keessattuu istikhaaraa\n    (filannoo kadhachuu) nu barsiisu turan. Ni jedhan: “tokkoon keessan\n    yeroo dhimmi wahii isa yaachise salaata waajibaatiin ala raka’aa\n    lama haa salaatu. Ergasii haa jedhu: ‘yaa Rabbi ani beekumsa\n    keetiinin si filachiifadha. Dandeettii keetiinin dandeettii si\n    kadha. Tola kee guddaa irraas sin kadha. Ati ni dandeessa ani hin\n    danda’u. Ati ni beekta ani hin beeku. Ati beekaa fagooti. Yaa Rabbi\n    yoo dhimmi kun, maqaa dhahee, naaf amantii kiyya keessatti, jiruufi\n    booda kiyya keessatti gaarii ta’e isa naaf murteessii naaf laaffisi.\n    Ergasii barakaa keessa naaf kaa’i. Yoo wanti kun amantii kiyya,\n    jireenya kiyyaafi booda kiyyaaf hamaa ta’uu kan beektu ta’e isa\n    narraa deebisii anas isarraa deebisi. Bakkuma jirutti toltuu naaf\n    murteessi. Ergasii isaan na jaaladhu.”"}, {"arabic": "وَمَا نَدِمَ مَنِ اسْتَخَارَ الْخَالِقَ، وَشَاوَرَ الْمَخْلُوقِينَ الْمُؤْمِنِينَ وَتَثَبَّتَ فِي أَمْرِهِ.", "oromo": "Namni Rabbiin filachiifatee, mu’umintoota maryachiisee\n    dhimma isaa mirkaneeffate hin gaabbu."}, {"arabic": "وَشَاوِرْهُمْ فِى ٱلْأَمْرِ ۖ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ", "oromo": "Rabbiin ol ta’e ni jedhe: “dhimmicha keessatti isaan\n    mariyachiisi. Yeroo murteeffatte Rabbirratti hirkadhu.” (Suuraa Aali\n    Imraan, aayaa 159)"}]}, {"num": 27, "arabicTitle": "أَذْكَارُ الصَّبَاحِ وَالْمَسَاءِ", "oromoTitle": "Zikriiwwan ganamaafi galgalaa", "duas": [{"arabic": "الْحَمْدُ لِلَّهِ وَحْدَهُ، وَالصَّلاَةُ وَالسَّلاَمُ عَلَى مَنْ لاَ نَبِيَّ بَعْدَهُ.", "oromo": "Faaruun kan Rabbii tokkichaati. Rahmanniifi nageenyi, Nabiyyii xumuraa\nirra haa jiraatu:"}, {"arabic": "اللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ\nلَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ\nيَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ\nوَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ", "oromo": "“Shayxaana rahmata Rabbii irraa fageeffamaa ta’e irraa Rabbittin\nmaganfadha: Rabbiin Isa malee haqaan gabbaramaan hin jiru. Inni\njiraataadha; waan hundaan dhaabbataadha. Mugaatiis ta’ee hirribni Isa\nhin qabatu. Wanti samii keessa jiruufi wanti dachii keessa jiru hundi\nkan Isaati. Inni hayyama Isaatiin ala Isa biratti araarsu eenyuma? Waan\nfuuldura isaaniitiifi waan duuba isaaniis ni beeka. Beekumsa Isaa irraas\nwaan Inni fedhetti malee hin marsanu. Kursiin Isaa samiifi dachii irra\nbal’ateera. Isaan lamaan tiksuun Isa hin dadhabsiisu. Inni ol ta’aa,\nguddaadha.”"}, {"arabic": "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\n\nقُلْ هُوَ ٱللَّهُ أَحَدٌ\n\nٱللَّهُ ٱلصَّمَدُ\n\nلَمْ يَلِدْ وَلَمْ يُولَدْ\n\nوَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ\n\nبِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\n\nقُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ\n\nمِن شَرِّ مَا خَلَقَ\n\nوَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ\n\nوَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ\n\nوَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ\n\nبِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\n\nقُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ\n\nمَلِكِ ٱلنَّاسِ\n\nإِلَٰهِ ٱلنَّاسِ\n\nمِنْ شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ\n\nٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ\n\nمِنَ ٱلْجِنَّةِ وَٱلنَّاسِ", "oromo": "Maqaa Rabbii Akkaan Mararfataa Akkaan Rahmata Godhaa Ta’eetiin. Jedhi: “Inni Allaah (gabbaramaa dhugaa) tokkicha. Allaahn\n    hirkoo waa hundaati. Hin dhalle hin dhalannes. Wanti tokkollee\n    fakkaataa Isaaf hin taane.”\n\nMaqaa Rabbii Akkaan Mararfataa Akkaan Rahmata Godhaa Ta’eetiin. Jedhi: “Gooftaa bariittin maganfadha. Hamtuu waan Inni\n    uumee irraa, hamtuu dukkanaa yeroo dukkanaa’e irraas, hamtuu\n    guduunfaa keessatti tuftu irraas, hamtuu haasidii yeroo inni\n    hassadu (waanyu) irraas, Rabbittin maganfadha.”\n\nMaqaa Rabbii Akkaan Mararfataa Akkaan Rahmata Godhaa Ta’eetiin. Jedhi: “Gooftaa namaattin maganfadha. Mootii namaatti,\n    Gabbaramaa namaatti, hamtuu waswaasii dhokatuufi mul’atuu irraa,\n    isa qoma namaa keessa waswaasu irraa, jinniifi nama irraa kan\n    ta’e irraan maganfadha.” Suuraalee sadan kana (Ikhlaas, Falaq,\n    Naas) ganamaafi galgala si’a sadii qara’i."}, {"arabic": "((أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ\nلاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ\nوَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيرَ مَا بَعْدَهُ،\nوَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ\nالْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ)).", "oromo": "“Nuti bariisifanne. Mootummaanis kan Rabbii ta’ee bule. Faaruun\n    kan Rabbiiti. Dhugaan gabbaramaan Rabbiin malee hin jiru. Inni\n    tokkicha hiriyaa hin qabneedha. Mootummaan kan isaati. Faaruunis kan\n    Isaati. Inni waan hunda irratti danda’aadha. Yaa Rabbi ani toltuu\n    guyyaa har’aa keessa jiruufi toltuu booda isaa jiru sin kadha.\n    Sherrii guyyaa harraa keessa jiruufi sherrii booda isaatii jiruu\n    irraa sittin maganfadha. Yaa Rabbi taatiyoo (nuffaa)fi dulluma hamaa\n    irraa sittin maganfadha. Yaa Rabbi adabbii ibidda keessaatiifi\n    adabbii qabrii keessaa irraa sittin maganfadha.”"}, {"arabic": "((اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ\nالنُّشُورُ)).", "oromo": "Yaa Rabbi siin bariisifannee siin dhiisifanne. Siin jiraannee\n    siin duuna. Deebiinis garuma keeti.”"}, {"arabic": "((اللَّهُمَّ أَنْتَ رَبِّي لاَ إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ\nوَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ\nبِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ)).", "oromo": "“Yaa Rabbi ati gooftaa kiyya. Situ na uumee ani gabricha keeti. Ani\n    hangan danda’een baallamaafi waadaa keerran jira. Hamtun hojjadhe\n    irraa Rabbittin maganfadha. Qananii ati natti oolte nan mirkaneessa.\n    Yakka kiyyas nan amana. Kan yakka araaramu si qofa waan ta’eef naa\n    araarami.”"}, {"arabic": "((اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلاَئِكَتِكَ، وَجَمِيعَ\nخَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لاَ إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لَكَ، وَأَنَّ مُحَمَّداً عَبْدُكَ\nوَرَسُولُكَ)) (أربعَ مَرَّاتٍ).", "oromo": "Yaa Rabbi ani si ragaa taasifataa, baattota Arshii keetii, maleykota\n    keetiifi uumama kee hunda akka ati Allaah taate, si malee haqaan kan\n    gabbaramu akka hin jirre, tokkicha hiriyaa hin qabneefi Muhammad\n    gabricha keetiifi ergamaa kee ta’uu ragaa baasifataan\n    bariisifadhe.” (si’a afur jedha)."}, {"arabic": "((اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لاَ\nشَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ)).", "oromo": "Yaa Rabbi qananii irraa wanti ana yookiin uumama kee irraa nama\n    tokko waliin bule sima qofa biraayyi. Ati tokkicha hiriyaa hin\n    qabneedha. Faaruun keeti; galannis kan keeti.”"}, {"arabic": "((اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي\nبَصَرِي،لاَ إِلَهَ إِلاَّ أَنْتَ. اللَّهُمَّ\nإِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ، وَالفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ القَبْرِ، لاَ إِلَهَ إِلاَّ أَنْتَ))\n(ثلاثَ مرَّاتٍ).", "oromo": "Yaa Rabbi qaama kiyya keessatti nagaa naa godhi. Yaa Rabbi\n    dhageettii kiyya keessatti nagaa na godhi. Yaa Rabbi agartuu kiyya\n    keessatti nagaa na godhi. Dhugaan gabbaramaan si malee hin jiru. Yaa\n    Rabbi ani kufriifi hiyyummaa irraa sittin maganfadha. Adabbii qabrii\n    irraas sittin maganfadha. Dhugaan gabbaramaan si malee hin jiru.”\n    (si’a sadii jedha)."}, {"arabic": "((حَسْبِيَ اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ\nعَلَيهِ تَوَكَّلتُ وَهُوَ رَبُّ الْعَرْشِ\nالْعَظِيمِ)) (سَبْعَ مَرّاتٍ).", "oromo": "“Gahaan kiyya Allaahdha. Dhugaan gabbaramaan Isa malee hin jiru.\n    Isarratti hirkadheera. Inni abbaa arshii guddaati.”(si’a torba\n    jedha)."}, {"arabic": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالآخِرَةِ، اللَّهُمَّ إِنِّي\nأَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ: فِي دِينِي وَدُنْيَايَ وَأَهْلِي، وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي،\nوَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَينِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي،\nوَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي)).", "oromo": "Yaa Rabbi ani addunyaafi aakhiraatti dhiifamaafi nageenyan si kadha.\n    Yaa Rabbi ani amantii, addunyaa, maatiifi qabeenya kiyya keessatti\n    dhiifamaafi nageenyan si kadha. Yaa Rabbi qaama kiyyas naa satari.\n    Sodaa irraas nagaa na godhi. Yaa Rabbi fuuldura kiyyaan, duuba\n    kiyyaan, mirga kiyyaan, bitaa kiyyaafi gubbaa kiyyaan na tiksi. Jala\n    kiyyaan gadi liqimfamuu irraas sittin maganfadha.”"}, {"arabic": "((اللَّهُمَّ عَالِمَ الغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ\nوَمَلِيكَهُ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطانِ\nوَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ)).", "oromo": "Yaa Rabbii beekaa fagoofi dhihoo! Uumaa samiifi dachii! Gooftaa waa\n    hundaafi horataa isaa kan taate! ‘Dhugaan gabbaramaan si malee hin\n    jiruu’ ragaan baha. Hamtuu lubbuu kiyyaa, hamtuu shayxaanaafi\n    shirkii isaa irraa sittin maganfadha. Akkasumas lubbuu koo irratti\n    hamtuu hojjachuu yookiin Muslima kamittuu harkisuu irraa sittin\n    maganfadha.”"}, {"arabic": "((بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلاَ فِي السّمَاءِ وَهُوَ\nالسَّمِيعُ الْعَلِيمُ)) (ثلاثَ مرَّاتٍ).", "oromo": "Maqaa Rabbii isa wanti tokkollee samiifi dachii keessatti maqaa Isaa\n    waliin hin miineetiin. Inni argaa beekaadha.” (si’a sadii\n    jedha)."}, {"arabic": "((رَضِيتُ بِاللَّهِ رَبَّاً، وَبِالْإِسْلاَمِ دِيناً، وَبِمُحَمَّدٍ × نَبِيّاً)) (ثلاثَ\nمرَّاتٍ).", "oromo": "Rabbiin gabbaramaa ta’uu, Islaamni amantii kiyya ta’uufi Muhammad\n    (saw) Nabiyyii naaf ta’uu jaaladheera.” (si’a sadii jedha)."}, {"arabic": "((يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغيثُ أَصْلِحْ لِي شَأْنِيَ كُلَّهُ وَلاَ تَكِلْنِي إِلَى\nنَفْسِي طَرْفَةَ عَيْنٍ)).", "oromo": "Yaa Rabbii jiraataa waan hunda to’ataa! Rahmata keen birmachiifadha.\n    Dhimma kiyya hunda naaf tolchi. Milluu ijaa tokkollee gara lubbuu\n    kiyyaatti na hin hirkisin.”"}, {"arabic": "((أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ\nهَذَا اليَوْمِ: فَتْحَهُ، وَنَصْرَهُ، وَنورَهُ، وَبَرَكَتَهُ، وَهُدَاهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا\nفِيهِ وَشَرِّ مَا بَعْدَهُ)).", "oromo": "Bariisifanne. Mootummaanis kan Rabbii mootii aalamaa ta’ee\n    bariisifate. Yaa Rabbi ani khayrii guyyaa kanaan si kadha:\n    injifannoo isaa, tumsa isaa, ifaa isaa, barakaa isaafi qajeeluma\n    isaa. Sherrii isa keessa jiruufi sherrii booda isaa jiru irraa\n    sittin maganfadha.”"}, {"arabic": "((أَصْبَحْنا عَلَى فِطْرَةِ الْإِسْلاَمِ، وَعَلَى كَلِمَةِ الْإِخْلاَصِ، وَعَلَى دِينِ\nنَبِيِّنَا مُحَمَّدٍ ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفاً مُسْلِماً وَمَا كَانَ مِنَ\nالْمُشرِكِينَ)).", "oromo": "Uumama Islaamaa irratti, jecha ikhlaasaa irratti, amantii Nabiyyii\n    keenya muhammad irrattiifi karaa abbaa keenyaa Ibraahiim irratti\n    Muslima sirrii taanee bariisifanne. Ibraahiim mushrika irraa\n    hin taane.”"}, {"arabic": "((سُبْحَانَ اللَّهِ وَبِحَمْدِهِ)) (مائة مرَّةٍ).", "oromo": "“Faaruu isaa waliinin qulqullina Rabbiin malu [isa qulqulleessa].”\n    (si’a dhibba jedha)."}, {"arabic": "((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى\nكُلِّ شَيْءٍ قَدِيرٌ)) (عشرَ مرَّات)، أَوْ (مرَّةً واحدةً عندَ الكَسَلِ).", "oromo": "Dhugaan gabbaramaan Rabbiin malee hin jiru. Inni tokkicha hiriyaa\n    hin qabneedha. Mootummaan kan isaati. Faaruunis kan Isaati. Inni\n    waan hunda irratti danda’aadha.” (si’a kudhan jedha yeroo\n    dadhabbii tokkicha jedha)."}, {"arabic": "((لاَ إِلَهَ إِلاَّ اللَّهُ، وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى\nكُلِّ شَيْءٍ قَدِيرٌ)) (مائةَ مرَّةٍ إذا أصبحَ).", "oromo": "Dhugaan gabbaramaan Rabbiin malee hin jiru. Inni tokkicha hiriyaa\n    hin qabneedha. Mootummaan kan isaati. Faaruunis kan Isaati. Inni\n    waan hunda irratti danda’aadha.” (Ganama si’a dhibba jedha)."}, {"arabic": "((سُبْحَانَ اللَّهِ وَبِحَمْدِهِ: عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ\nكَلِمَاتِهِ)) (ثلاثَ مرَّاتٍ إذا أصبحَ).", "oromo": "Faaruu isaa waliin qulqullina Rabbiin malun [isa qulqulleessa]:\n    hanga baay’ina uumama isaatiin, hanga jaalala lubbuu isaatiin, hanga\n    madaala arshii isaatiifi maddii barreeffama jecha isaatiin.” (Ganama\n    si’a sadii jedha)."}, {"arabic": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نَافِعاً، وَرِزْقاً طَيِّباً، وَعَمَلاً مُتَقَبَّلاً)) (إذا\nأصبحَ).", "oromo": "Yaa Rabbi ani barumsa fayyadu, soorata gaariifi hojii qeebalamtuun\n     si kadha.” (Ganama)"}, {"arabic": "((أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ)) (مِائَةَ", "oromo": "Araaraman Rabbiin kadha. Badii irraas gara Isaattin deebi’a.”\n     (Guyyaatti si’a dhibba jedhe)"}, {"arabic": "((أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ)) (ثلاثَ مرَّاتٍ إذا\nأمسى).", "oromo": "Hamtuu waan inni uumee irraa jecha Rabbii guutuuttin maganfadha.”\n     (Galgala si’a sadii)"}, {"arabic": "((اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبَيِّنَا مُحَمَّدٍ)) (عشرَ مرَّاتٍ).", "oromo": "Yaa Rabbi rahmataafi nageenya Nabiyyii keenya Muhammad irratti\n     buusi.” (si’a kudhan)"}]}, {"num": 28, "arabicTitle": "أَذْكَارُ النَّوْمِ", "oromoTitle": "Zikriiwwan hirribaa", "duas": [{"arabic": "((يَجْمَعُ كَفَّيْهِ ثُمَّ يَنْفُثُ فِيهِمَا فَيَقْرَأُ فِيهِمَا: قُلْ هُوَ اللَّهُ أَحَدٌ، اللَّهُ الصَّمَدُ، لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ. قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ، مِنْ شَرِّ مَا خَلَقَ، وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ، وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ، وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ. قُلْ أَعُوذُ بِرَبِّ النَّاسِ، مَلِكِ النَّاسِ، إِلَهِ النَّاسِ، مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ، الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ، مِنَ الْجِنَّةِ وَالنَّاسِ (ثَلَاثَ مَرَّاتٍ)، ثُمَّ يَمْسَحُ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ، يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ وَمَا أَقْبَلَ مِنْ جَسَدِهِ (يَفْعَلُ ذَلِكَ ثَلَاثَ مَرَّاتٍ)).", "oromo": "Harka isaa lamaan walitti qabee isaan keessatti qara’ee afuufa: “Maqaa Rabbii Akkaan Mararfataa Akkaan Rahmata Godhaa Ta’eetiin. Jedhi: ‘Inni Allaah (gabbaramaa dhugaa) tokkicha. Allaahn hirkoo waa hundaati. Hin dhalle hin dhalannes. Wanti tokkollee fakkaataa Isaaf hin taane.’ Maqaa Rabbii Akkaan Mararfataa Akkaan Rahmata Godhaa Ta’eetiin. Jedhi: ‘Gooftaa bariittin maganfadha. Hamtuu waan Inni uumee irraa, hamtuu dukkanaa yeroo dukkanaa’e irraas, hamtuu guduunfaa keessatti tuftu irraas, hamtuu haasidii yeroo inni hassadu (waanyu) irraas, Rabbittin maganfadha.’ Maqaa Rabbii Akkaan Mararfataa Akkaan Rahmata Godhaa Ta’eetiin. Jedhi: ‘Gooftaa namaattin maganfadha. Mootii namaatti, Gabbaramaa namaatti, hamtuu waswaasii dhokatuufi mul’atuu irraa, isa qoma namaa keessa waswaasu irraa, jinniifi nama irraa kan ta’e irraan maganfadha.’ (si’a sadii) Eegasii harka isaa lameeniin qaama isaarraa waan dhaqqabe haxaawa. Matarraa jalqabee fuula isaatiifii gama fuulduraa qaama isaa akkanatti oofa, yoggu sadihi kana raawwata."}, {"arabic": "اللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ\nلَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ\nيَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ\nوَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ", "oromo": "Rabbiin Isa malee haqaan gabbaramaan hin jiru. Inni jiraataadha; waan hundaan dhaabbataadha. Mugaatiis ta’ee hirribni Isa hin qabatu. Wanti samii keessa jiruufi wanti dachii keessa jiru hundi kan Isaati. Inni hayyama Isaatiin ala Isa biratti araarsu eenyuma? Waan fuuldura isaaniitiifi waan duuba isaaniis ni beeka. Beekumsa Isaa irraas waan Inni fedhetti malee hin marsanu. Kursiin Isaa samiifi dachii irra bal’ateera. Isaan lamaan tiksuun Isa hin dadhabsiisu. Inni ol ta’aa, guddaadha."}, {"arabic": "آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ، كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ، لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ، وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ. لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا، لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ، رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا، رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا، رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ، وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا، أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ.", "oromo": "Ergamichi waan Gooftaa isaa irraa gara isaatti buufametti amaneera; mu’uminoonnis amananiiru. Hundumtuu Rabbitti, malaa’ikoota Isaatti, kitaabota Isaafi ergamoota Isaatti amananiiru. “Nuti ergamoota Isaa irraa tokkollee adda hin baafnu” [jedhan]. “Nuti dhageenye; ajajamnes. Gooftaa keenya! Araarama kee [barbaanna]. Deebiinis garuma keeti” jedhan. Rabbiin lubbuu tokkollee dandeettii isheetiin ala hin dirqisiisu. [Toltuu irraa] wanti isheen carraaqqate isheedhumaafi; [hamtuu irraa] wanti isheen carraaqqattes ishee irratti ta’a. Gooftaa keenya! Yoo daganne yookiin dogoggorre nu hin qabin. Gooftaa keenya! Ba’aa guddaa akka warra nuun duraa irratti baachifte nurratti hin baachisin. Gooftaa keenya! Waan isatti dandeettiin nuuf hin jirre nu hin baachisin. Irras nuuf dabri; nuuf araarami. Rahmatas nuuf godhi. Ati gargaaraa keenya. Ummata kaafirootaa irrattis nuuf tumsi."}, {"arabic": "((بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِن أَمْسَكْتَ نَفْسِي فارْحَمْهَا،\nوَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا، بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ)).", "oromo": "“Yaa Rabbi maqaa keetiinin cinaacha kiyya keeyyadhe. Siinin ol\n     kaasa. Yoo lubbuu kiyya fuuteef ishee mararfadhu. Yoo ishee\n     deebiftee ergiteef waan gabroottan kee gaggaarii tiksituun ishee\n     tiksi.”"}, {"arabic": "((اللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْياهَا، إِنْ أَحْيَيْتَهَا\nفَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا. اللَّهُمَّ إِنِّي أَسْأَلُكَ العَافِيَةَ)).", "oromo": "Yaa Rabbi ati lubbuu kiyya uumteetta. Situ ishee ajjeesa. Duutiifi\n     jireenyi ishee kan keeti. Yoo ishee jiraachifteef ishee tiksi. Yoo\n     ishee ajjeefteef isheef araarami. Yaa Rabbi ani nageenyan si\n     kadha.”"}, {"arabic": "((اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ)).", "oromo": "Yaa Rabbi guyyaa gabroottan kee kaaftu ibidda kee irraa na tiksi.”\n     (si’a sadii)"}, {"arabic": "((بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا)).", "oromo": "Yaa Rabbi maqaa keetiinin du’a; isaanin jiraadhas.”"}, {"arabic": "((سُبْحَانَ اللَّهِ (ثلاثاً وثلاثين) وَالْحَمْدُ لِلَّهِ (ثلاثاً وثلاثين) وَاللَّهُ\nأَكْبَرُ (أربعاً وثلاثينَ))).", "oromo": "Rabbiin qulqullina isaan malu qulqullaa’e. Faaruun kan Rabbiiti.”\n     (si’a soddomii sadii) “Rabbiin hundarra guddaadha.” (si’a soddomii\n     afur)."}, {"arabic": "((اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الأَرْضِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ\nكُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ، وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ\nشَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ. اللَّهُمَّ أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الآخِرُ\nفَلَيسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ\nعَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ)).", "oromo": "Yaa Allaah gooftaa samii torbaniifi gooftaa arshii guddaa, gooftaa\n     keenyaafi gooftaa waa hundaa, yaa Rabbii keenyaafi Rabbii waa\n     hundaa! Biqilchaa midhaaniifi nakhlii! Yaa buusaa Tawraat,\n     Injiiliifi Furqaan! Sherrii waa hundaa kan ati sammuu isaa qabde\n     irraa sittin maganfadha. Yaa Rabbi ati jalqaba; si dura homaa hin\n     jiru. Ati booda jiraataadha; si booda homaa hin jiru. Ati hundaa\n     oli; gubbaa kee homaa hin jiru. Ati iccitii beekaadha; wanti sirraa\n     dhokatu hin jiru. Hidaa nurraa kaffalii hiyyummaa irraa nu\n     duroomsi.”"}, {"arabic": "((الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا، فَكَمْ مِمَّنْ لاَ كَافِيَ\nلَهُ وَلاَ مُؤْوِيَ)).", "oromo": "Faaruun kan Rabbii isa nu nyaachisee, nu obaasee, nuuf gaheefi nu\n     qubsiiseeti. Meeqaatamatu waan isaaf gahuufi isa qubsiisu hin\n     qabne!”"}, {"arabic": "((اللَّهُمَّ عَالِمَ الغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ\nوَمَلِيكَهُ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطانِ\nوَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ)).", "oromo": "Yaa Rabbii beekaa fagoofi dhihoo! Uumaa samiifi dachii! Gooftaa waa\n     hundaafi horataa isaa kan taate! ‘Dhugaan gabbaramaan si malee hin\n     jiruu’ ragaan baha. Hamtuu lubbuu kiyyaa, hamtuu shayxaanaafi\n     finyoo (haada) isaa irraa sittin maganfadha. Akkasumas lubbuu koo\n     irratti hamtuu hojjachuu yookiin Muslima kamittuu harkisuu irraa\n     sittin maganfadha.”"}, {"arabic": "((يَقْرَأُ ﴿الــم﴾ تَنْزِيلَ السَّجْدَةِ، وَتَبَارَكَ الَّذي بِيَدِهِ الْمُلْكُ)).", "oromo": "Suurat Assajdaafi suurat Almulk qara’a."}, {"arabic": "((اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي\nإِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لاَ مَلْجَأَ وَلاَ مَنْجَا مِنْكَ إِلاَّ إِلَيْكَ،\nآمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ)).", "oromo": "Yaa Rabbi lubbuu kiyya sitti kenneera. Dhimma kiyyas gara keetti\n     hirkiseera. Fuula kiyyas gara keetti deebiseera. Dugda kiyyas gara\n     keetti hirkiseera. Rahmata kee kajeelaa adabbii kee sodaataa. Bakki\n     sirraa itti dabaniifi itti bilisa ta’an gara kee malee hin jiru.\n     Kitaaba kee ati buufteefi Nabiyyii kee ati ergitetti\n     amaneera.”"}]}, {"num": 29, "arabicTitle": "الدُّعَاءُ إِذَا تَقَلَّبَ لَيْلاً", "oromoTitle": "Du’aa’ii yeroo hirriba keessa gara galanii", "duas": [{"arabic": "(لاَ إِلَهَ إِلاَّ اللَّهُ الْوَاحِدُ الْقَهّارُ، رَبُّ السَّمَوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا\nالْعَزيزُ الْغَفَّارُ)).", "oromo": "Dhugaan gabbaramaan Rabbii tokkicha injifataa malee hin jiru. Inni\n     Rabbii samii, dachiifi waan jidduu isaaniiti. Injifataa\n     araaramaadha.”"}]}, {"num": 30, "arabicTitle": "دُعَاءُ الْفَزَعِ فِي النَّوْمِ وَمَنْ بُلِيَ بِالْوَحْشَةِ", "oromoTitle": "Du’aa’ii naasuu hirriba keessaafi nama bineensa wahiitiin rifatee", "duas": [{"arabic": "(أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ\nالشَّياطِينِ وَأَنْ يَحْضُرُونِ)).", "oromo": "Dallansuu Rabbii, adabbii isaa, hamtuu gabroottan isaa, nama\n     maraachisuu shayxaanaafi natti dhufuu irraa jecha Rabbii guutuu\n     ta’ettin maganfadha.”"}]}, {"num": 31, "arabicTitle": "مَا يَفْعَلُ مَنْ رَأَى الرُّؤْيَا أَوِ الْحُلْمَ", "oromoTitle": "Waan namni manaama yookaan abjuu fokkataa arge hojjatu", "duas": [{"arabic": "((يَنْفُثُ عَنْ يَسَارِهِ)) (ثَلاَثاً).", "oromo": "Bitaa isaa irraan yeroo sadii afuufa."}, {"arabic": "((يَسْتَعِيذُ بِاللَّهِ مِنَ الشَّيطَانِ وَمِنْ شَرِّ مَا رَأَى)) (ثَلاَثَ مَرَّاتٍ).", "oromo": "Si’a sadii shayxaanaafi hamtuu arge irraa Rabbitti maganfata."}, {"arabic": "((لاَ يُحَدِّثْ بِهَا أَحَداً)).", "oromo": "Nama tokkottuu isa hin himu."}, {"arabic": "((يَتَحَوَّلُ عَنْ جَنْبِهِ الَّذِي كَانَ عَلَيْهِ)).", "oromo": "Cinaacha irra ture irraa ni jijjiirrata."}, {"arabic": "((يَقُومُ يُصَلِّي إِنْ أَرَادَ ذَلِكَ)).", "oromo": "Yoo fedheef ol ka’ee salaata."}]}, {"num": 32, "arabicTitle": "دُعاءُ قُنُوتِ الوِتْرِ", "oromoTitle": "Du’aa’ii qunuutii witrii", "duas": [{"arabic": "((اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ،\nوَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلاَ يُقْضَى عَلَيْكَ، إِنَّهُ لاَ\nيَذِلُّ مَنْ وَالَيْتَ، [وَلاَ يَعِزُّ مَنْ عَادَيْتَ]، تَبارَكْتَ رَبَّنا وَتَعَالَيْتَ)).", "oromo": "Yaa Rabbi warra qajeelchitee wajjin na qajeelchi; warra nagaa\n     gootee wajjin nagaa na godhi; warra jaalalloo godhattee wajjin\n     jaalalloo na godhadhu. Waan kennite keessa barakaa naaf godhi.\n     Hamtuu waan murteessite irraa na tiksi. Ati ni murteessita sirratti\n     hin murteeffamu waan ta'eef. Dubbiin, nama ati jaalalloo godhatte\n     wanti xiqqeessu hin jiru. [Nama ati diina godhatte kan kabaju hin\n     jiru]. Yaa Rabbii keenya tolli kee baay'ateera; ol\n     taateettas.\""}, {"arabic": "((اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُـــــوذُ\nبِكَ مِنْكَ، لاَ أُحْصِي ثَنَاءً عَلَيْـكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ)).", "oromo": "Yaa Rabbi ani dallansuu keerraa jaalala keetti, adabbii kee irraa\n     nageenya keettin maganfadha. Faaruu kee lakkaa’ee hin fixu. Ati\n     akkuma lubbuu kee faarsiteedha.”"}, {"arabic": "((اللَّهُمَّ إِيَّاكَ نعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ، وَإِلَيْكَ نَسْعَى وَنَحْفِدُ، نَرْجُو رَحْمَتَكَ،\nوَنَخْشَى عَذَابَكَ، إِنَّ عَذَابَكَ بِالكَافِرِينَ مُلْحَقٌ. اللَّهُمَّ إِنَّا نَسْتَعينُكَ، وَنَسْتَغْفِرُكَ، وَنُثْنِي\nعَلَيْكَ الْخَيْرَ، وَلاَ نَكْفُرُكَ، وَنُؤْمِنُ بِكَ، وَنَخْضَعُ لَكَ، وَنَخْلَعُ مَنْ يَكْفرُكَ)).", "oromo": "Yaa Rabbi si qofa gabbarra. Siif salaannee siif sujuunna. Gara\n     keetti fiigna jaalala keetti ariifanna. Rahmata kee kajeellaa.\n     Adabbii kee sodaanna. Adabbiin kee kaafiroota qunnamaadha. Yaa\n     Rabbi si gargaarsifanna. Araaramas sirra barbaanna. Gaariidhaan si\n     faarsina. Si hin morminu. Sitti amanna siif ajajamna. Nama si mormu\n     irraa ni fagaanna.”"}]}, {"num": 33, "arabicTitle": "الذِّكْرُ عَقِبَ السَّلاَمِ مِنَ الْوِتْرِ", "oromoTitle": "Zikrii yeroo witrii irraa salaamtaa bahanii", "duas": [{"arabic": "(سُبْحَانَ المَلِكِ القُدُّوسِ)) ثلاثَ مرَّاتٍ والثَّالِثَةُ يَجْهَرُ بها ويَمُدُّ بها صَوتَهُ\nيقولُ: [رَبِّ الْمَلاَئِكَةِ وَالرُّوحِ])).", "oromo": "Mootii qulqulluu, qulqullina isaan malun [qulqulleessa]. Si’a sadii\n     jedha. Ishee sadaffaa sagalee ol fuudhee dheeressee jedha. Ergasii\n     “Rabbii maleykaafi Jibriil” jechuu dabala."}]}, {"num": 34, "arabicTitle": "دُعَاءُ الْهَمِّ وَالْحُزْنِ", "oromoTitle": "Du’aa’ii yaaddoofi gaddaa", "duas": [{"arabic": "((اللَّهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ،\nعَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُــــلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ،\nأَوْ عَلَّمْتَهُ أَحَداً مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ القُرْآنَ\nرَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجَلاَءَ حُزْنِي، وَذَهَابَ هَمِّي)).", "oromo": "Yaa Rabbi ani gabricha keeti. Ilma gabricha keetiiti. Ilma\n     gabrittii keetiiti. Sammuun kiyya sirka jira. Murtiin kee narratti\n     raawwatamaadha. Murtiin kee anaaf haqa. Maqaa kee hundaa kan ati\n     ittiin of moggaafte, yookiin kitaaba kee keessatti buufte, yookiin\n     uumama kee irraa tokko barsiifte yookiin beekumsa fagoo si bira\n     jiru keessatti filatteenin akka ati Qur'aana boqonnaa qalbii\n     kiyyaa, ifaa qoma kootii, dhabamsiisaa gadda kiyyaatiifi deemsisaa\n     yaaddoo kiyyaa taasiftun Si kadha.”"}, {"arabic": "((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ\nوَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ)).", "oromo": "Yaa Rabbi ani yaaddoofi gadda, dadhabbiifi taatiyoo, doynummaafi\n     luynummaa, hidaan ulfaachuufi namootaan mo’atamuu irraa sittin\n     maganfadha.”"}]}, {"num": 35, "arabicTitle": "دُعَـــــــاءُ الْكَـــــرْبِ", "oromoTitle": "Du’aa’ii Yeroo Cinqii", "duas": [{"arabic": "((لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ\nالْعَظِيمِ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ)).", "oromo": "Dhugaan gabbaramaan Rabbii guddaa obsaa malee hin jiru. Dhugaan\n     gabbaramaan Rabbii arshii guddaa malee hin jiru. Dhugaan\n     gabbaramaan Rabbii samii, dachiifi Rabbii arshii guddaa malee hin\n     jiru.”"}, {"arabic": "((اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي\nكُلَّهُ، لاَ إِلَهَ إِلاَّ أَنْتَ))", "oromo": "Yaa Rabbi rahmata keen kajeelaa milluu ijaatiif lubbuu kiyyatti na\n     hin hirkisin. Dhimma kiyya hundaa naaf gaaromsi. Dhugaan\n     gabbaramaan si malee hin jiru.”"}, {"arabic": "((لاَ إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظّالِمِينَ)).", "oromo": "Dhugaan gabbaramaan si malee hin jiru. Sin qulqulleessa. Ani\n     miidhaa raawwattoota irraa ta’eera.”"}, {"arabic": "((اللَّهُ اللَّهُ رَبِّي لاَ أُشْرِكُ بِهِ شَيْئاً)).", "oromo": "Allaahn gooftaa kiyya homaa Isatti hin qindeessu.”"}]}, {"num": 36, "arabicTitle": "دُعَاءُ لِقَاءِ الْعَدُوِّ وَذِي السُّلْطَانِ", "oromoTitle": "Du’aa’ii yeroo diinaafi abbaa taayitaa qunnaman godhamu", "duas": [{"arabic": "((اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِم، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ)).", "oromo": "Yaa Rabbi nuti qoma isaanii keessa si godhanna. Hamtuu isaanii\n     irraa sitti maganfanna.”"}, {"arabic": "((اللَّهُمَّ أَنْتَ عَضُدِي، وَأَنْتَ نَصِيرِي، بِكَ أَحُولُ وَبِكَ أَصُولُ، وَبِكَ\nأُقاتِلُ)).", "oromo": "Yaa Rabbi ati irree kooti. Ati gargaaraa kooti. Siinin tooftaa\n     baafadha. Siinin diina injifadha. Siinin diinaan lola.”"}, {"arabic": "((حَسْبُنا اللَّهُ وَنِعْمَ الْوَكِيلُ)).", "oromo": "Gahaan keenya Rabbii isarratti hirkachuun waa tole!”"}]}, {"num": 37, "arabicTitle": "دُعَاءُ مَنْ خَافَ ظُلْمَ السُّلْطَانِ", "oromoTitle": "Du’aa’ii nama miidhaa mootii sodaatee", "duas": [{"arabic": "((اللَّهُمَّ ربَّ السَّمَوَاتِ السَّبْعِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، كُنْ لِي جَاراً مِنْ فُلاَنِ\nبْنِ فُلاَنٍ، وَأَحْزَابِهِ مِنْ خَلاَئِقِكَ، أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ يَطْغَى، عَزَّ جَارُكَ، وَجَلَّ\nثَنَاؤُكَ، وَلاَ إِلَهَ إِلاَّ أَنْتَ)).", "oromo": "Yaa Allaah gooftaa samii torbanii! Gooftaa arshii guddaa! Abalu\n     ilma abaluufi humnoota isaa, tokkoon isaanii daangaa natti taruu\n     yookiin na miidhuu irraa tiksaa naaf ta’i. Tiksaan kee guddate.\n     Faaruun keetis guddate. Dhugaan gabbaramaan si malee hin\n     jiru.”"}, {"arabic": "((اللَّهُ أَكْبَرُ، اللَّهُ أَعَزُّ مِنْ خَلْقِهِ جَمِيعاً، اللَّهُ أَعَزُّ مِمَّا أَخَافُ وَأَحْذَرُ،\nأَعُوذُ بِاللَّهِ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ، الْمُمْسِكِ السَّمَوَاتِ السَّبْعِ أَنْ يَقَعْنَ عَلَى الْأَرْضِ\nإِلاَّ بِإِذْنِهِ، مِنْ شَرِّ عَبْدِكَ فُلاَنٍ، وَجُنُودِهِ وَأَتْبَاعِهِ وَأَشْيَاعِهِ، مِنْ الْجِنِّ وَالإِنْسِ،\nاللَّهُمَّ كُنْ لِي جَاراً مِنْ شَرِّهِمْ، جَلَّ ثَنَاؤُكَ وَعَزَّ جَارُكَ، وَتَبَارَكَ اسْمُكَ، وَلاَ إِلَهَ غَيْرُكَ))\n(ثلاثَ مرَّاتٍ).", "oromo": "Rabbiin hundarra guddaadha. Rabbiin uumama isaa hundarra guddaadha.\n     Rabbiin waan ani sodaadhu hundarra injifataadha. Rabbii isa dhugaan\n     gabbaramaan isa malee hin jirre, kan akka samiin torban eeyyama\n     isaatiin malee dachii irra hin buune qabettin hamtuu gabricha kee\n     abaluu, loltoota isaa, hordoftootaafi jaalalloo isaa jinniifi\n     namoota irraa ta’an irraa maganfadha. Yaa Rabbi hamtuu isaanii\n     irraa nagaa baasaa naaf ta’i. Faaruun kee guddate; nagaa godhuun\n     keetis guddate. Maqaan kee toltuun isaa baay’ate. Dhugaan\n     gabbaramaan si malee hin jiru.” (si’a sadii)"}]}, {"num": 38, "arabicTitle": "الدُّعَاءُ عَلَى الْعَدُوِّ", "oromoTitle": "Du’aa’ii Diina irratti godhamu", "duas": [{"arabic": "(اللَّهُمَّ مُنْزِلَ الْكِتَابِ، سَرِيعَ الْحِسَابِ، اهْزِمِ الأَحْزَابَ، اللَّهُمَّ اهزِمْهُمْ\nوَزَلْزِلْهُمْ)).", "oromo": "Yaa Rabbii buusaa kitaabaa! Qorannoo ariifataa! Garee diinaa\n     bittinneessi. Yaa Rabbi isaan bittinneessii isaan urgufi.”"}]}, {"num": 39, "arabicTitle": "مَا يَقُولُ مَنْ خَافَ قَوْماً", "oromoTitle": "Waan namni ummata wahii sodaate jedhu", "duas": [{"arabic": "(اللَّهُمَّ اكْفِنِيهِمْ بِمَا شِئْتَ)).", "oromo": "Yaa Rabbi waan feeteen isaan narraa gahi.”"}]}, {"num": 40, "arabicTitle": "دُعَاءُ مَنْ أَصَابَهُ وَسْوَسَةٌ فِي الإِيمَانِ", "oromoTitle": "Du’aa’ii nama shakkiin iimaana keessatti isa mudatee", "duas": [{"arabic": "((يَسْتَعِيذُ بِاللَّهِ)).", "oromo": "Rabbitti maganfata."}, {"arabic": "((يَنْتَهِي عَمَّا وَسْوَسَ فِيهِ)).", "oromo": "Waan shakke sana irraa ni dhaabbata."}, {"arabic": "((يَقُولُ: آمَنْتُ بِاللَّهِ وَرُسُلِهِ)).", "oromo": "“Rabbiifi ergamoota isaatti amaneera” jedha."}, {"arabic": "((يَقْرَأُ قَوْلَهُ تَعَالَى: ﴿هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ، وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ﴾)).", "oromo": "Jecha Rabbii kana qara’a: “Inni duruma jira; kan boodaatis; mul’ataadha; dhokataas [argaadha]; Inni waan hunda beekaadha.”"}]}, {"num": 41, "arabicTitle": "دُعَاءُ قَضَاءِ الدَّيْنِ", "oromoTitle": "Du’aa’ii hidaa kaffaluu", "duas": [{"arabic": "((اللَّهُمَّ اكْفِنِي بِحَلاَلِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكِ عَمَّنْ سِوَاكَ)).", "oromo": "Yaa Rabbi halaala keetiin haraama kee irraa na tiksi. Tola keetiin\n     waan si malee jiru irraa of na geessisi.”"}, {"arabic": "((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ\nوَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ)).", "oromo": "Yaa Rabbi ani yaaddoofi gadda, dadhabbiifi taatiyoo, doynummaafi\n     lunnummaa, ulfina hidaafi namootaan mo’atamoo irraa sittin\n     maganfadha.”"}]}, {"num": 42, "arabicTitle": "دُعَاءُ الوَسْوَسَةِ فِي الصَّلاَةِ وَالْقِرَاءَةِ", "oromoTitle": "Du’aa’ii woswaasii salaataafi Qur'aana keessatti nama mudateef godhamu", "duas": [{"arabic": "(أَعُوذُ بِاللَّهِ مِنَ الشَّيطَانِ الرَّجِيمِ، وَاتْفُلْ عَلَى يَسَارِكَ (ثلاثاً))).", "oromo": "Shayxaana abaaramaa irraa Rabbittin maganfadha.” Ergasii gara\n     bitaatti yeroo sadii tufa."}]}, {"num": 43, "arabicTitle": "دُعَاءُ مَنِ اسْتَصْعَبَ عَلَيْهِ أَمْرٌ", "oromoTitle": "Du’aa’ii nama dhimmi wahii itti ulfaate", "duas": [{"arabic": "(اللَّهُمَّ لاَ سَهْلَ إِلاَّ مَا جَعَلْتَهُ سَهْلاً، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ\nسَهْلاً)).", "oromo": "Yaa Rabbi waan ati laaffifte malee laafaan hin jiru. Ati yeroo\n     feete gadda laafaa taasifta.”"}]}, {"num": 44, "arabicTitle": "مَا يَقُولُ وَيَفْعَلُ مَنْ أَذْنَبَ ذَنْباً", "oromoTitle": "Waan namni yakka hojjate jedhuufi hojjatu", "duas": [{"arabic": "(مَا مِنْ عَبْدٍ يُذنِبُ ذَنْباً فَيُحْسِنُ الطُّهُورَ، ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ، ثُمَّ يَسْتَغْفِرُ\nاللَّهَ إِلاَّ غَفَرَ اللَّهُ لَهُ)).", "oromo": "Gabrichi tokko yoo yakka wahii raawwatee wuduu gaaromfatee ergasii\n     dhaabbatee raka’aa lama salaatee sana booda araarama Rabbiin\n     kadhate Rabbiin isaaf araaramu malee hin hafu.”"}]}, {"num": 45, "arabicTitle": "دُعَاءُ طَرْدِ الشَّيطَانِ وَوَسَاوِسِهِ", "oromoTitle": "Du’aa’ii shayxaanaafi woswaasii isaa ari’u", "duas": [{"arabic": "((الْاسْتِعَاذَةُ بِاللَّهِ مِنْهُ)).", "oromo": ""}, {"arabic": "((الْأَذَانُ)).", "oromo": ""}, {"arabic": "((الْأَذْكَارُ وَقِرَاءَةُ الْقُرْآنِ)).", "oromo": "Isarraa Rabbitti maganfachuu."}]}, {"num": 46, "arabicTitle": "الدُّعَاءُ حِينَمَا يَقَعُ مَا لاَ يَرْضَاهُ أَوْ غُلِبَ عَلَى أَمْرِهِ", "oromoTitle": "Du’aa’ii namni wanti inni hin feene itti argame godhu", "duas": [{"arabic": "(قَدَرُ اللَّهِ وَمَا شَاءَ فَعَلَ)).", "oromo": "[Kun] murtii Rabbiiti. Waan fedhe hojjata.”"}]}, {"num": 47, "arabicTitle": "تَهْنِئَةُ المَوْلُودِ لَهُ وَجَوَابُهُ", "oromoTitle": "Waan nama daa’imni dhalateef ittiin eebbisaniifi deebii isaa", "duas": [{"arabic": "(بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوبِ لَكَ، وَشَكَرْتَ الْوَاهِبَ، وَبَلَغَ أَشُدَّهُ، وَرُزِقْتَ\nبِرَّهُ)). وَيَرُدُّ عَلَيْهِ الْمُهَنَّــــــأُ فَيَقُولُ: ((بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ،\nوَجَزَاكَ اللَّهُ خَيْراً، وَرَزَقَكَ اللَّهُ مِثْلَهُ، وَأَجْزَلَ ثَوَابَكَ)).", "oromo": "“Waan siif kenname keessa Rabbiin barakaa siif haa kaa’u. Isa siif\n     kenne kan galateeffattu ta’i. Ga’eessuma irras haa ga’u. Toltuu\n     isaas Rabbiin siif haa kennu.” Inni eebbifamu immoo ni jedha:\n     “Rabbiin barakaa siif haa godhu. Barakaa sirras haa godhu. Mindaa\n     toltuu siif haa godhu. Fakkaataa isaa Rabbiin siifis haa kennu.\n     Mindaa kee haa guddisu.”"}]}, {"num": 48, "arabicTitle": "ما يُعوَّذُ بِهِ الأَوْلاَدُ", "oromoTitle": "Waan ilmaan ittiin tiksan", "duas": [{"arabic": "كَانَ رَسُولُ اللَّهِ صيُعَوِّذُ الحَسَنَ وَالحُسَينَ ^ ((أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ\nكُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لاَمَّةٍ)).", "oromo": "Nabiyyiin (saw) Hasaniifi Huseeniin kan armaan gadiitiin tiksu\n     ture: “jecha Rabbii guutuu ta’eenin shayxaanaafi summii ajjeeftu\n     hunda irraa, ija (budaa) hamtuu deddeebitu irraa isin tiksa.”"}]}, {"num": 49, "arabicTitle": "الدُّعَاءُ لِلْمَرِيضِ فِي عِيَادَتِهِ", "oromoTitle": "Du’aa’ii yeroo dhukkubsataa gaafatan godhamuuf", "duas": [{"arabic": "((لاَ بأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ)).", "oromo": ""}, {"arabic": "((أَسْأَلُ اللَّهَ الْعَظيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفيَكَ)) (سبع مرات).", "oromo": "Homaa miti; yoo Rabbiin fedhe qulqulleessituudha.”"}]}, {"num": 50, "arabicTitle": "فَضْلُ عِيَادَةِ المَرِيضِ", "oromoTitle": "Sadarkaa dhukkubsataa gaafachuu", "duas": [{"arabic": "قَالَ النَّبِيُّ ص: ((إِذَا عَادَ الرَّجُلُ أَخَاهُ الْمُسْلِمَ مَشَى فِي خِرَافَةِ الْجَنَّةِ حَتَّى\nيَجْلِسَ، فَإِذَا جَلَسَ غَمَرَتْهُ الرَّحْمَةُ، فَإِنْ كَانَ غُدْوَةً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى\nيُمْسِيَ، وَإِنْ كَانَ مَسَاءً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُصْبِحَ)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “namni tokko yeroo obboleessa isaa\n     Muslimaa gaafate hanga taa’utti fuduraa jannataa funaannachuu\n     keessa deemaa jira. Yeroo taa’e rahmanni isa haguugdi. Yoo ganama\n     ta’eef hanga dhihutti maleykaan kumni torbaatamni rahmata isaaf\n     kadhatti. Yoo galgala ta’e immoo hanga ifutti maleykaan kumni\n     torbaatamni rahmata isaaf kadhatti.”"}]}, {"num": 51, "arabicTitle": "دُعَاءُ المَرِيضِ الَّذِي يَئِسَ مِنْ حَيَاتِهِ", "oromoTitle": "Du’aa’ii dhukkubsataa jireenya irraa abdii kutee", "duas": [{"arabic": "((اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى)).", "oromo": "Yaa Rabbi naaf araarami; na mararfadhu. Hiriyootii ol aanootti na\n     dhaqqabsiisi.”"}, {"arabic": "((جَعَلَ النَّبِيُّ ص عِنْدَ مَوْتِهِ يُدْخِلُ يَدَيْهِ فِي الْمَاءِ فَيَمْسَحُ بِهِمَا وَجْهَهُ،\nوَيَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ إِنَّ لِلْمَوْتِ سَكَرَاتٍ)).", "oromo": "Nabiyyiin (saw) yeroo du’an harka isaanii bishaan keessa galchanii\n     fuula isaanii ittiin haxaa’anii “dhugaan gabbaramaan Rabbiin malee\n     hin jiru. Duuti dhugumatti machii qaba.”"}, {"arabic": "((لاَ إِلَهَ إِلاَّ اللَّهُ وَاللَّهُ أَكْبَرُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ، لاَ إِلَهَ إِلاَّ\nاللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لاَ إِلَهَ إِلاَّ اللَّهُ لَهُ المُلْكُ وَلَهُ الْحَمْدُ، لاَ إِلَهَ إِلاَّ\nاللَّهُ وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)).", "oromo": "Dhugaan gabbaramaan Rabbiin malee hin jiru. Rabbiin guddates.\n     Dhugaan gabbaramaan Rabbii tokkicha malee hin jiru. Dhugaan\n     gabbaramaan Rabbii tokkicha hiriyaa hin qabne malee hin jiru.\n     Dhugaan gabbaramaan Rabbiin malee hin jiru. Mootummaan kan Isaati;\n     faaruunis kan isaati. Dhugaan gabbaramaan Rabbiin malee hin jiru.\n     Tooftaafi humni Rabbiin biraa malee hin jiru.”"}]}, {"num": 52, "arabicTitle": "تَـلْـــــقِينُ الـمُحْـــــتَضَرِ", "oromoTitle": "Nama duuti itti dhufe laqqansiisuu", "duas": [{"arabic": "(مَنْ كَانَ آخِرُ كَلاَمِهِ لاَ إِلَهَ إِلاَّ اللَّهُ دَخَلَ الْجَنَّةَ)).", "oromo": "Namni dhumti haasaa isaa “dhugaan gabbaramaan Rabbiin malee hin\n     jiru” jechuu ta’e jannata gala."}]}, {"num": 53, "arabicTitle": "دُعَاءُ مَن أُصِيبَ بِمُصِيبَةٍ", "oromoTitle": "Du’aa’ii nama rakkoon isa mudatee", "duas": [{"arabic": "(إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرَاً\nمِنْهَا)).", "oromo": "Nuti kan Rabbiiti. Nuti gara Isaa deebi’oodhas. Yaa Rabbi rakkoo\n     kiyya keessatti na mindeessi. Kan isa caalu bakka naaf buusi.”"}]}, {"num": 54, "arabicTitle": "الدُّعَاءُ عِنْدَ إِغْمَاضِ المَيِّتِ", "oromoTitle": "Du’aa’ii yeroo ija du’aa gadi qaban jedhamu", "duas": [{"arabic": "(اللَّهُمَّ اغْفِرْ لِفُلاَنٍ (بِاسْمِهِ) وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ، وَاخْلُفْهُ فِي عَقِبِهِ\nفِي الْغَابِرِينَ، وَاغْفِرْ لَنَا وَلَهُ\nيَا رَبَّ الْعَالَمِينَ، وَافْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ)).", "oromo": "Yaa Rabbi abaluuf araarami. Sadarkaa isaa qajeeltota keessatti ol\n     kaasi. Booda isaatii warra hafan keessatti bakka buusiif. Yaa\n     Rabbii aalamaa nuufi isaafis araarami. Qabrii isaa keessa isaaf\n     ballisi; keessa isaa isaaf ibsi.”"}]}, {"num": 55, "arabicTitle": "الدُّعَاءُ لِلمَيِّتِ فِي الصَّلاَةِ عَلَيْهِ", "oromoTitle": "Du’aa’ii yeroo janaazaa irratti salaatanuu", "duas": [{"arabic": "((اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ، وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ،\nوَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الأَبْيَضَ مِنَ\nالدَّنَسِ، وَأَبْدِلْهُ دَاراً خَيْراً مِنْ دَارِهِ، وَأَهْلاً خَيْراً مِنْ أَهْلِهِ، وَزَوْجَاً خَيْراً مِنْ زَوْجِهِ،\nوَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ القَبْرِ [وَعَذَابِ النَّارِ])).", "oromo": "Yaa Rabbi isaaf araarami. Isa mararfadhu. Nagaa isa godhi. Irra\n     dabriif. Qubsuma isaa kabaji. Seensa isaa ballisiif. Bishaan,\n     bishaan qabbanaafi cabbiin isa miici. Akka huccuu adii xurii irraa\n     qulqulleessitetti yakka irraa isa qulqulleessi. Mana mana isaa\n     caalu, maatii maatii isaa caalaniifi niitii niitii isaa caaltu\n     bakka buusiif. Jannata isa seensisi. Adabbii qabriitiifi adabbii\n     ibiddaa irraa isa tiksi.”"}, {"arabic": "((اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبيرِنَا،\nوَذَكَرِنَا وَأُنْثَانَا. اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلاَمِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا\nفَتَوَفَّهُ عَلَى الإِيمَانِ، اللَّهُمَّ لاَ تَحْرِمْنَا أَجْرَهُ، وَلاَ تُضِلَّنَا بَعْدَهُ)).", "oromo": "Yaa Rabbi jiraataafi du’aa keenyaaf, dhihoofi fagoo keenyaaf,\n     xiqqoofi guddaa keenyaaf, dhiiraafi dhalaa keenyaaf araarami. Yaa\n     Rabbi nama nurraa jiraachifte Islaama irratti jiraachisi. Nama\n     nurraa ajjeefte immoo iimaana irratti ajjeesi. Yaa Rabbi mindaa\n     isaa nu hin hongeessin. Booda isaatiis nu hin jallisin.”"}, {"arabic": "((اللَّهُمَّ إِنَّ فُلاَنَ بْنَ فُلاَنٍ فِي ذِمَّتِكَ، وَحَبْلِ جِوَارِكَ، فَقِهِ مِنْ فِتْنَةِ الْقَبْرِ،\nوَعَذَابِ النَّارِ، وَأَنْتَ أَهْلُ الْوَفَاءِ وَالْحَقِّ، فَاغْفِرْ لَهُ وَارْحَمْهُ إِنَّكَ أَنْتَ الغَفُورُ\nالرَّحِيمُ)).", "oromo": "Yaa Rabbi abalu ilma abaluu eegumsa keetiifi waadaa nageenya keetii\n     keessa jira. Mokkkoroo qabriifi adabbii ibiddaa irraa isa tiksi.\n     Ati abbaa waadaa guutuufi haqaati. Isaaf araarami. Isa mararfadhu.\n     Ati simatu araaramaa mararfataadha.”"}, {"arabic": "((اللَّهُمَّ عَبْدُكَ وَابْنُ أَمَتِكَ احْتَاجَ إِلَى رَحْمَتِكَ، وَأَنْتَ غَنِيٌّ عَنْ عَذَابِهِ، إِنْ\nكَانَ مُحْسِناً فَزِدْ فِي حَسَنَاتِهِ، وَإِنْ كَانَ مُسِيئاً فَتَجَاوَزْ عَنْهُ)).", "oromo": "Yaa Rabbi gabrichi keetiifi ilmi gabrittii keetii rahmata keetti\n     haajomeera. Ati adabbii isaa irraa dureessa. Yoo inni gaarii\n     hojjataa ta’e gaarii isaa dabaliif. Yoo yakkamaa ta’e irra\n     dabriif.”"}]}, {"num": 56, "arabicTitle": "الدُّعَاءُ لِلْفَرَطِ فِي الصَّلاةِ عَلَيْهِ", "oromoTitle": "Du’aa’ii ilmoo du’eef godhamu  salaata irratti salaatamu keessatti.", "duas": [{"arabic": "((اللَّهُمَّ أَعِذْهُ مِنْ عَذَابِ القَبْرِ)).", "oromo": ""}, {"arabic": "وإن قال: ((اللَّهُمَّ اجْعَلْهُ فَرَطاً وَذُخْراً لِوَالِدَيْهِ، وَشَفِيعاً مُجَاباً، اللَّهُمَّ ثَقِّلْ بِهِ\nمَوَازِينَهُمَا، وَأَعْظِمْ بِهِ أُجورَهُمَا، وَأَلْحِقْهُ بِصَالِحِ الْمُؤْمِنِينَ، وَاجْعَلْهُ فِي كَفَالَةِ\nإِبْرَاهِيمَ، وَقِهِ بِرَحْمَتِكَ عَذَابَ الْجَحِيمِ، وَأَبْدِلْهُ دَاراً خَيْراً مِنْ دَارِهِ، وَأَهْلاً خَيْراً مِنْ\nأَهْلِهِ، اللَّهُمَّ اغْفِرْ لِأَسْلاَفِنَا، وَأَفْرَاطِنَا، وَمَنْ سَبَقَنَا بِالْإِيمَانِ)) فَحَسَنٌ.", "oromo": ""}, {"arabic": "((اللَّهُمَّ اجْعَلْهُ لَنَا فَرَطاً، وَسَلَفاً، وَأَجْراً)).", "oromo": "Yaa Rabbi adabbii qabrii irraa isa tiksi.”"}]}, {"num": 57, "arabicTitle": "دُعَـــــــاءُ التَّعْــــــــزِيَةِ", "oromoTitle": "Du’aa’ii taaziyaa (gaddaa)", "duas": [{"arabic": "(إِنَّ للَّهِ مَا أَخَذَ، وَلَهُ مَا أَعْطَى، وَكُلُّ شَيْءٍ عِنْدَهُ بِأَجَلٍ مُسَمَّى... فَلْتَصْبِرْ\nوَلْتَحْتَسِبْ)).", "oromo": ""}, {"arabic": "وَإِنْ قَالَ: ((أَعْظَمَ اللَّهُ أَجْرَكَ، وَأَحْسَنَ عَزَاءَكَ، وَغَفَرَ لِمَيِّتِكَ)) فَحَسَنٌ.", "oromo": "Wanti Rabbiin fudhate kan Isaati. Kan Inni kennes kan Isaati. Wanti\n     hunduu Isa biratti baallama beekamaadhaani. … haa obsitu mindaa\n     Rabbirratti haa herreggattu.”"}]}, {"num": 58, "arabicTitle": "الدُّعَاءُ عِنْدَ إِدْخَالِ الميِّتِ الْقَبْرَ", "oromoTitle": "Du’aa’ii yeroo du’aa qabrii galchan godhamu", "duas": [{"arabic": "(بِسْمِ اللَّهِ وَعَلَى سُنَّةِ رَسُولِ اللَّهِ)).", "oromo": "Maqaa Rabbiitiin; karaa Ergamaa Rabbii (saw) irratti.”"}]}, {"num": 59, "arabicTitle": "الدُّعَاءُ بَعْدَ دَفْنِ المَيِّتِ", "oromoTitle": "Du’aa’ii erga du’aa awwaalanii godhamu", "duas": [{"arabic": "(اللَّهُمَّ اغْفِرْ لَهُ، اللَّهُمَّ ثَبِّتْهُ)).", "oromo": "Yaa Rabbi araaramiif. Yaa Rabbi gadi isaa dhaabi.”"}]}, {"num": 60, "arabicTitle": "دُعَاءُ زِيَارَةِ الْقُبُورِ", "oromoTitle": "Du’aa’ii yeroo qabrii ziyaaranii", "duas": [{"arabic": "(السَّلاَمُ عَلَيْكُمْ أَهْلَ الدِّيَارِ، مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ\nبِكُمْ لاَحِقُونَ، [وَيَرْحَمُ اللَّهُ الْمُسْتَقدِمِينَ مِنَّا وَالْمُسْتأْخِرِينَ] أَسْاَلُ اللَّهَ لَنَا وَلَكُمُ\nالْعَافِيَةَ)).", "oromo": "Yaa warra ganda mu’umintootaafi muslimoota irraa taatan nagaan isin\n     irra haa jiraatu. Nuti yoo Rabbiin fedhe isinitti dhaqqaboodha.\n     Rabbiin nurraa warra durseefis ta’ee kan boodaatiif haa araaramu.\n     Nuufi isiniif nageenyan kadha.”"}]}, {"num": 61, "arabicTitle": "دُعَـــــــاءُ الرِّيـــــــــــح", "oromoTitle": "Du’aa’ii yeroo qilleensaa", "duas": [{"arabic": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا)).", "oromo": "Yaa Rabbi ani toltuu isheen si kadha. Hamtuu ishee irraa sittin\n     maganfadha.”"}, {"arabic": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيهَا، وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ\nبِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيهَا، وَشَرِّ مَا أُرْسِلَتْ بِهِ)).", "oromo": "Yaa Rabbi ani toltuu ishee, toltuu ishee keessa jiruufi toltuu\n     isheen ittiin ergamten si kadha. Hamtuu ishee, hamtuu ishee keessa\n     jiruufi hamtuu isheen ittiin ergamte irraa sittin maganfadha.”"}]}, {"num": 62, "arabicTitle": "دُعَـــــاءُ الرَّعْــــــــدِ", "oromoTitle": "Du’aa’ii kakawwee (mandiisuu)", "duas": [{"arabic": "(سُبْحَانَ الَّذِي يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ وَالْمَلاَئِكةُ مِنْ خِيفَتِهِ)).", "oromo": "Rabbiin inni kakawween faaruu isaa waliin, maleykaanis sodaa\n     isaatiin isa qulqulleessan qulqullaa’eera.”"}]}, {"num": 63, "arabicTitle": "مِنْ أَدْعِيَةِ الاسْتِسْقَاءِ", "oromoTitle": "Du’aa’ii istisqaa’ii (rooba barbaachaa)", "duas": [{"arabic": "((اللَّهُمَّ اسْقِنَا غَيْثاً مُغِيثاً مَرِيئاً مَرِيعاً، نَافِعاً غَيْرَ ضَارٍّ، عَاجِلاً غَيْرَ\nآجِلٍ)).", "oromo": "Yaa Rabbi bokkaa roobu, gaarii, waa biqilchu, kan fayyadu hin\n     miine, ariifataa kan hin turre nu obaasi.”"}, {"arabic": "((اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا)).", "oromo": "Yaa Rabbi nuuf roobsi. Yaa Rabbi nuuf roobsi. Yaa Rabbi nuuf\n     roobsi.”"}, {"arabic": "((اللَّهُمَّ اسْقِ عِبَادَكَ، وَبَهَائِمَكَ، وَانْشُرْ رَحْمَتَكَ، وَأَحْيِي بَلَدَكَ\nالْمَيِّتَ)).", "oromo": "Yaa Rabbi gabroottan keetiifi bineensota obaasi. Rahmata kee\n     ballisi. Biyya kee du’e fayyisi.”"}]}, {"num": 64, "arabicTitle": "الدُّعَاءُ إِذَا رَأَى المَطَرَ", "oromoTitle": "Du’aa’ii yeroo roobni roobu godhamu", "duas": [{"arabic": "(اللَّهُمَّ صَيِّباً نَافِعاً)).", "oromo": "Yaa Rabbi rooba fayyadu [taasisi].”"}]}, {"num": 65, "arabicTitle": "الذِّكْرُ بَعْدَ نُزُولِ المَطَرِ", "oromoTitle": "Zikrii booda roobni roobee jedhamu", "duas": [{"arabic": "(مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ)).", "oromo": "Tola Rabbiitiifi rahmata isaatiin nuuf roobe.”"}]}, {"num": 66, "arabicTitle": "مِنْ أَدْعِيَةِ الاسْتِصْحَاءِ", "oromoTitle": "Du’aa’ii rooba sirreessuuf godhamu", "duas": [{"arabic": "(اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا، اللَّهُمَّ عَلَى الآكَامِ وَالظِّرَابِ، وَبُطُونِ الْأَوْدِيَةِ،\nوَمَنَابِتِ الشَّجَرِ)).", "oromo": "Yaa Rabbi naannoo keenyatti roobsi malee nurratti hin roobsin. Yaa\n     Rabbi sibboofi gaara, garaa laggeeniifi hundee biqilootaa irratti\n     godhi.”"}]}, {"num": 67, "arabicTitle": "دُعَاءُ رُؤيَةِ الهِلاَلِ", "oromoTitle": "Du’aa’ii yeroo baatii arganii", "duas": [{"arabic": "(اللَّهُ أَكْبَرُ، اللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِالْأَمْنِ وَالْإِيمَانِ، وَالسَّلاَمَةِ وَالْإِسْلاَمِ،\nوَالتَّوْفِيقِ لِمَا تُحِبُّ رَبَّنَا وَتَرْضَى، رَبُّنَا وَرَبُّكَ اللَّهُ)).", "oromo": "Rabbiin hundarra guddate. Yaa Rabbi nageenyaafi iimaanaan,\n     nageenyaafi Islaamaan, waan ati jaalattuufi feetuuf waffaqamuu\n     waliin nurratti baasi. Rabbiin keenyaafi Rabbiin kee\n     Allaahdha.”"}]}, {"num": 68, "arabicTitle": "الدُّعَاءُ عِنْدَ إِفْطَارِ الصَّائِمِ", "oromoTitle": "Du’aa’ii yeroo fixrii godhamu", "duas": [{"arabic": "((ذَهَبَ الظَّمَأُ وَابْتَلَّتِ العُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ)).", "oromo": "Dheebuun deeme. Hiddi dhiigaa jiidheera. Yoo Rabbiin fedhe\n     mindaanis mirkanaa’eera.”"}, {"arabic": "((اللَّهُمَّ إِنِّي أَسْأَلُكَ بِرَحْمَتِكَ الَّتِي وَسِعَتْ كُلَّ شَيْءٍ أَنْ تَغْفِرَ لِي)).", "oromo": "Yaa Allaah ani rahmata kee kan waan hunda wal gaheenin naaf\n     araaramuu si kadha.”"}]}, {"num": 69, "arabicTitle": "الدُّعَاءُ قَبْلَ الطَّعَامِ", "oromoTitle": "Du’aa’ii nyaata duraa", "duas": [{"arabic": "((إِذَا أَكَلَ أَحَدُكُمْ طَعَاماً فَلْيَقُلْ بِسْمِ اللَّهِ، فَإِنْ نَسِيَ فِي أَوَّلِهِ فَلْيَقُلْ بسمِ\nاللَّهِ فِي أَوَّلِهِ وَآخِرِهِ)).", "oromo": "Tokkoon keessan yeroo nyaachuuf ka’e “maqaa Rabbiitiin” haa jedhu.\n     Yoo jalqaba irratti dagate “jalqaba isaatiifi dhuma isaas maqaa\n     Rabbiitiin [eegale]” haa jedhu."}, {"arabic": "((مَنْ أَطْعَمَهُ اللَّهُ الطَّعَامَ فَلْيَقُلْ: اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَأَطْعِمْنَا خَيْراً\nمِنْهُ، وَمَنْ سَقَاهُ اللَّهُ لَبَناً فَلْيَقُلْ اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ)).", "oromo": "Namni Rabbiin nyaata wahii isa nyaachise “yaa Rabbi barakaa isa\n     keessa nuuf godhi. Kan isa caalu nu nyaachisi” haa jedhu. Namni\n     Rabbiin aannan isa obaase “yaa Rabbi barakaa isa keessa nuuf kaa’i.\n     Isarraa nuuf dabalis” haa jedhu."}]}, {"num": 70, "arabicTitle": "الدُّعَاءُ عِنْدَ الْفَرَاغِ مِنَ الطَّعَامِ", "oromoTitle": "Du’aa’ii yeroo nyaata xumuranii", "duas": [{"arabic": "((الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا، وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ\nقُوَّةٍ)).", "oromo": "Faaruun kan Rabbii kana na nyaachiseeti. Tooftaafi humna na biraa\n     hin ta’iniin isa na soore.”"}, {"arabic": "((الْحَمْدُ لِلَّهِ حَمْداً كَثِيراً طَيِّباً مُبَارَكاً فِيهِ، غَيْرَ [مَكْفِيٍّ وَلاَ ] مُوَدَّعٍ،\nوَلاَ مُسْتَغْنَىً عَنْهُ رَبَّنَا)).", "oromo": "Faaruun kan Rabbiiti. Faaruu baay’ee gaarii barakaa qabu kan irraa\n     of hin geenye, isa hin dhiifneefi irraa hin duroomnen [si faarsa]\n     yaa Rabbii keenya.”"}]}, {"num": 71, "arabicTitle": "دُعَاءُ الضَّيْفِ لِصَاحِبِ الطَّعَامِ", "oromoTitle": "Du’aa’ii keessummaan abbaa nyaataatiif godhu", "duas": [{"arabic": "(اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُم، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ)).", "oromo": "Yaa Rabbi waan isaan soorte keessa barakaa kaa’iif. Isaaniif\n     araaramii isaan mararfadhu.”"}]}, {"num": 72, "arabicTitle": "التَّعْرِيضُ بِالدُّعَاءُ لِطَلَبِ الطَّعَامِ أَوِ الشَّرَابِ", "oromoTitle": "Du’aa’ii nama isa obaaseef godhamu", "duas": [{"arabic": "(اللَّهُمَّ أَطْعِمْ مَنْ أَطْعَمَنِي، وَاسْقِ مَنْ سَقَانِي)).", "oromo": "Yaa Rabbi nama na nyaachise nyaachisi. Nama na obaases\n     obaasi.”"}]}, {"num": 73, "arabicTitle": "الدُّعَاءُ إِذَا أَفْطَرَ عِنْدَ أَهْلِ بَيْت", "oromoTitle": "Du’aa’ii maatii biratti faxiraniif godhamu", "duas": [{"arabic": "(أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ\nالْمَلاَئِكَةُ)).", "oromo": "Soomtotatu isin biratti fure. Gaggaariitu nyaata keessan nyaate.\n     Maleykaanis du’aa’ii isiniif kadhatti.”"}]}, {"num": 74, "arabicTitle": "دُعَاءُ الصَّائِمِ إِذَا حَضَرَ الطَّعَامُ وَلَمْ يُفْطِرْ", "oromoTitle": "Du’aa’ii namni ogga nyaanni itti dhufee furuu dhiise godhu", "duas": [{"arabic": "(إِذَا دُعِيَ أحَدُكُم فَلْيُجِبْ، فَإِنْ كَانَ صَائِماً فَلْيُصَلِّ، وَإِنْ كَانَ مُفْطِراً\nفَلْيَطْعَمْ))، وَمَعْنَى فَلْيُصَلِّ أَيْ فَلْيَدْعُ.", "oromo": "Tokkoon keessan yeroo affeerame haa owwaatu. Yoo kan soomu ta’eef\n     du’aa’ii haa godhu. Yoo furee jiraateef haa nyaatu.”"}]}, {"num": 75, "arabicTitle": "مَا يَقُولُ الصَّائِمُ إِذَا سَابَّهُ أَحَدٌ", "oromoTitle": "Waan namni soomu yeroo arrabsame jedhu", "duas": [{"arabic": "(إِنِّي صَائِمٌ، إِنِّي صَائِمٌ)).", "oromo": "Ani nan soomaara; ani nan soomaara.”"}]}, {"num": 76, "arabicTitle": "الدُّعَاءُ عِنْدَ رُؤْيَةِ بَاكُورَةِ الثَّمَرِ", "oromoTitle": "Du’aa’ii yeroo fuduraa haaraa arganii", "duas": [{"arabic": "(اللَّهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا، وَبَارِكْ لَنَا فِي مَدِينَتِنَا، وَبَارِكْ لَنَا فِي\nصَاعِنَا، وَبَارِكْ لَنَا فِي مُدِّنَا)).", "oromo": "Yaa Rabbi fuduraa keenya keessa barakaa nuuf kaa’i. Yaa Rabbi\n     Madiinaa keenya keessas barakaa nuuf kaa’i. Saa’ii keenya keessas\n     barakaa nuuf kaa’i. Konyee keenya keessas barakaa nuuf kaa’i.”"}]}, {"num": 77, "arabicTitle": "دُعَاءُ الْعُطَاسِ", "oromoTitle": "Du’aa’ii axxiffoo", "duas": [{"arabic": "((إِذَا عَطَسَ أَحَدُكُم فَلْيَقُلِ الْحَمْدُ لِلَّهِ، وَلْيَقُلْ لَهُ أَخُوهُ أَوْ صَاحِبُهُ: يَرْحَمُكَ\nاللَّهُ، فَإِذَا قَالَ لَهُ: يَرحَمُكَ اللَّهُ، فَلْيَقُلْ: يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ)).", "oromo": "Tokkoon keessan yeroo axxiffate “faaruun kan Rabbiiti” haa jedhu.\n     Obboleessi yookiin hiriyaan isaa immoo “Rabbiin si haa mararfatu”\n     haa jedhuun. Ogga inni “Rabbiin si haa mararfatu” jedhe immoo\n     “Rabbiin sin haa qajeelchu; haala keessanis haa tolchu” haa\n     jedhuun."}]}, {"num": 78, "arabicTitle": "مَا يُقَالُ لِلْكَافِرِ إِذَا عَطَسَ فَحَمِدَ الله", "oromoTitle": "Waan yeroo kaafirri axxiffatee Rabbiin faarse jedhamuun", "duas": [{"arabic": "((يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ)).", "oromo": "“Rabbiin sin haa qajeelchu.”"}]}, {"num": 79, "arabicTitle": "الدُّعَاءُ لِلْمُتَزَوِّجِ", "oromoTitle": "Du’aa’ii nama fuudheef godhamu", "duas": [{"arabic": "(بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ)).", "oromo": "Rabbiin barakaa siif haa godhu. Barakaa sirrattis haa godhu.\n     Toltuudhaan jidduu keessan walitti haa qabu.”"}]}, {"num": 80, "arabicTitle": "دُعَاءُ المُتَزَوِّجِ وَشِرَاءِ الدَّابَّةِ", "oromoTitle": "Du’aa’ii nama fuudheefi beellada bitee", "duas": [{"arabic": "إِذَا تَزَوَّجَ أَحَدُكُمُ امْرَأَةً، أَوْ إِذَا اشْتَرَى خَادِماً فَلْيَقُلْ: ((اللَّهُمَّ إِنِّي أَسْأَلُكَ\nخَيْرَهَا، وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ، وَإِذَا\nاشْتَرَى بَعِيراً فَلْيَأْخُذْ بِذِرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ)).", "oromo": "Tokkoon keessan yeroo dubartii fuudhe yookiin tajaajilaa bite kana\n     haa jedhu: “yaa Rabbi ani toltuu isheetiifi toltuu waan ati irratti\n     ishee uumteen si kadha. Hamtuu isheetiifi hamtuu waan ati irratti\n     ishee uumtee irraa sittin maganfadha.” Yeroo gaala bite gooba isaa\n     qabee fakkii kanaa haa jedhu."}]}, {"num": 81, "arabicTitle": "الدُّعَاءُ قَبْلَ إِتْيَانِ الزَّوْجَةِ", "oromoTitle": "Du’aa’ii haadha manaatiin wal qunnamuun dura godhamu", "duas": [{"arabic": "(بِسْمِ اللَّهِ، اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا)).", "oromo": "Maqaa Rabbiitiin; yaa Rabbi shayxaana irraa nu fageessi. Waan nuuf\n     arjoomte irraas shayxaana fageessi.”"}]}, {"num": 82, "arabicTitle": "دُعَــــاءُ الْغَضَــــــبِ", "oromoTitle": "Du’aa’ii yeroo dallansuu", "duas": [{"arabic": "(أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ)).", "oromo": "Shayxaana abaaramaa irraa Rabbittin maganfadha.”"}]}, {"num": 83, "arabicTitle": "دُعَاءُ مَنْ رَأَى مُبْتَلَىً", "oromoTitle": "Du’aa’ii namni nama mokkoramaa arge godhu", "duas": [{"arabic": "(الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلاَكَ بِهِ، وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ\nتَفْضِيلاً)).", "oromo": "Faaruun kan Rabbii waan ittiin si mokkore irraa nagaa na godheefi\n     waan uume baay’ee irra na caalchiseeti.”"}]}, {"num": 84, "arabicTitle": "مَا يُقَالُ فِي المَجْلِسِ", "oromoTitle": "Waan taa’icha keessatti jedhamu", "duas": [{"arabic": "(عَنِ ابْنِ عُمَرَ رضي الله عنه قَاَلَ: كَانَ يُعَدُّ لِرَسُولِ اللَّهِ فِي الْمَجْلِسِ الوَاحِدِ\nمِائَةُ مَرَّةٍ مِنْ قَبْلِ أَنْ يَقُومَ: ((رَبِّ اغْفِرْ لِي، وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ\nالغَفُورُ)).", "oromo": "Ibn Umar irraa odeeffamee (ra) ni jedhe: Ergamaa Rabbiitiif (saw)\n     taa’icha tokko keessatti si’a dhibba tokko “yaa Rabbi naaf\n     araarami; tawbaa kiyya qeebali. Ati simatu akkaan tawbaa qeebalaa\n     araaramaadha waan taateef” jechuu lakkoofna ture."}]}, {"num": 85, "arabicTitle": "كَفَّارَةُ المَجْلِسِ", "oromoTitle": "Waan badii taa’ichaa harcaasu", "duas": [{"arabic": "(سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ\nإِلَيْكَ)).", "oromo": "Yaa Rabbi faaruu keetii waliinin si qulqulleessa. Dhugaan\n     gabbaramaan si malee hin jiruu ragaan baha. Araaraman si kadha.\n     Gara keettin deebi’as.”"}]}, {"num": 86, "arabicTitle": "الدُّعَاءُ لِمَنْ قَالَ غَفَرَ اللهُ لَك", "oromoTitle": "Du’aa’ii nama ‘Rabbiin siif haa araaramu’ jedheef godhamu", "duas": [{"arabic": "(وَلَكَ)).", "oromo": "“Siifis haa araaramu.”"}]}, {"num": 87, "arabicTitle": "الدُّعَاءُ لِمَنْ صَنَعَ إِلَيْكَ مَعْرُوفاً", "oromoTitle": "Du’aa’ii nama toltuu sii ooleef gootu", "duas": [{"arabic": "(جَزَاكَ اللَّهُ خَيْراً)).", "oromo": "Rabbiin toltuu si haa mindeessu.”"}]}, {"num": 88, "arabicTitle": "مَا يَعْصِمُ اللَّهُ بِهِ مِنَ الدَّجَّـــــــالِ", "oromoTitle": "Waan Rabbiin ittiin Dajjaal irraa nama tiksu", "duas": [{"arabic": "(مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الْكَهْفِ عُصِمَ مِنَ الدَّجَّالِ))،\nوَالْاسْتِعَاذَةُ بِاللَّهِ مِنْ فِتْنَتِهِ عَقِبَ التَّشَهُّدِ الْأَخِيرِ مِنْ كُلِّ صَلاَةٍ.", "oromo": "Namni jalqaba suuraa Kahf irraa aayata kudhan haffaze Dajjaal irraa\n     tikfama.”"}]}, {"num": 89, "arabicTitle": "الدُّعَاءُ لِمَنْ قَالَ إِنِّي أُحِبُّكَ فِي اللَّهِ", "oromoTitle": "Waan nama ‘Rabbiif jechan si jaaladha’ jedheen jedhamu", "duas": [{"arabic": "(أَحَبَّكَ الَّذِي أَحْبَبْتَنِي لَهُ)).", "oromo": "Inni ati isaaf jecha na jaalatte si haa jaalatu.”"}]}, {"num": 90, "arabicTitle": "الدُّعَاءُ لِمَنْ عَرَضَ عَلَيْكَ مَالَهُ", "oromoTitle": "Du’aa’ii nama qabeenya isaa sii kenneef gootu", "duas": [{"arabic": "(بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ)).", "oromo": "Rabbiin maatii keetiifi qabeenya kee keessa barakaa siif haa\n     godhu.”"}]}, {"num": 91, "arabicTitle": "الدُّعَاءُ لِمَنْ أَقْرَضَ عِنْدَ القَضَاءِ", "oromoTitle": "Du’aa’ii yeroo hidaan kaffalamu nama kaffaluuf godhamu", "duas": [{"arabic": "(بارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ، إِنَّمَا جَزَاءُ السَّلَفِ الْحَمْدُ\nوَالأَدَاءُ)).", "oromo": "Rabbiin maatii keetiifi qabeenya kee keessa barakaa siif haa kaa’u.\n     Mindaan hidaa galataafi kafaltiidha.”"}]}, {"num": 92, "arabicTitle": "دُعَاءُ الْخَوْفِ مِنَ الشِّرْكِ", "oromoTitle": "Du’aa’ii nama shirkii irraa sodaatee", "duas": [{"arabic": "(اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لاَ\nأَعْلَمُ)).", "oromo": "Yaa Rabbi ani osoon beekuu sitti qindeessuu irraa sittin\n     maganfadha. Waan hin beekneef immoo araaraman si kadha.”"}]}, {"num": 93, "arabicTitle": "الدُّعَاءُ لِمَنْ قَالَ بَارَكَ اللَّهُ فِيكَ", "oromoTitle": "Du’aa’ii nama ‘Rabbiin barakaa si keessa haa godhu’ jedheen godhamu", "duas": [{"arabic": "(وَفِيكَ بَارَكَ اللَّهُ)).", "oromo": "Si keessas barakaan haa godhamu.”"}]}, {"num": 94, "arabicTitle": "دُعَاءُ كَرَاهِيَةِ الطِّيَرَةِ", "oromoTitle": "Du’aa’ii namni hixaa fokkataa sodaate godhu", "duas": [{"arabic": "(اللَّهُمَّ لاَ طَيْرَ إِلاَّ طَيْرُكَ، وَلاَ خَيْرَ إِلاَّ خَيْرُكَ، وَلاَ إِلَهَ غَيْرُكَ)).", "oromo": "Yaa Rabbi hixaan hixaa kee malee hin jiru. Toltuunis toltuu kee\n     malee hin jiru. Dhugaan gabbaramaan si malee hin jiru.”"}]}, {"num": 95, "arabicTitle": "دُعَاءُ الرُّكُوبِ", "oromoTitle": "Du’aa’ii nama geejjiba yaabbatee", "duas": [{"arabic": "(بِسْمِ اللَّهِ، وَالْحَمْدُ للَّهِ )) }سُبْحانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ\nمُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ{، ((الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ،\nاللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، سُبْحَانَكَ اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي؛\nفَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ)).", "oromo": "Maqaa Rabbiitiin. Faaruun kan Rabbiiti. “Inni kana nuuf laaffise\n     qulqullaa’e; nuti isa danda’oo hin turre. Nuti gara Gooftaa keenyaa\n     deebi’oodha.” Faaruun kan Rabbiiti. Faaruun kan Rabbiiti.\n     Faaruun kan Rabbiiti. Rabbiin hundarra guddaadha. Rabbiin hundarra\n     guddaadha. Rabbiin hundarra guddaadha. Yaa Rabbi ati qulqulloofte.\n     Yaa Rabbi ani lubbuu kiyya miidheeraa naaf araarami. Dubbiin, si\n     malee kan yakka araaramu hin jiru.”"}]}, {"num": 96, "arabicTitle": "دُعَــــاءُ السَّــــــفَرِ", "oromoTitle": "Du’aa’ii imalaa", "duas": [{"arabic": "((اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، سُبْحانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ، اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا البِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَليفَةُ فِي الْأَهْلِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمَنْظَرِ، وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ))، وإذا رَجَعَ قَالَهُنَّ وَزَادَ فِيهِنَّ: ((آيِبُونَ، تائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ)).", "oromo": "Rabbiin hundarra guddaadha. Rabbiin hundarra guddaadha. Rabbiin\n     hundarra guddaadha. “Inni kana nuuf laaffise qulqullaa’e; nuti isa\n     danda’oo hin turre. Nuti gara Gooftaa keenyaa deebi’oodha.”\n     Yaa Rabbi nuti imala keenya kana keessatti toltuufi tika, hojii\n     irraa waan ati jaallattun si kadha. Yaa Rabbi imala keenya kana\n     nuuf laaffisi. Fageenya isaa nurraa mari. Yaa Rabbi imala keessatti\n     situ shariika; maatii keessatti situ bakka bu’aadha. Yaa Rabbi\n     cinqii imalaa, ilaalcha gaddisiisaafi deebii hamaa qabeenyaafi\n     maatii keessatti arguu irraa sittin maganfadha.” Yeroo deebi’es\n     kana jedhee kan armaan gadii itti ida’a: “nuti deebi’oodha; yoo\n     Rabbiin fedhe toobbataa, Rabbiin gabbaraa, Rabbii keenya\n     faarsaadha.”"}]}, {"num": 97, "arabicTitle": "دُعاءُ دُخُولِ القريَةِ أَوِ البَلْدَةِ", "oromoTitle": "Du’aa’ii yeroo magaalaa yookiin biyya seenanii", "duas": [{"arabic": "(اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَمَا أَظْلَلْنَ، وَرَبَّ الأَرَضِينَ السَّبْعِ وَمَا أَقْلَلْنَ،\nوَرَبَّ الشَّياطِينِ وَمَا أَضْلَلْنَ، وَرَبَّ الرِّيَاحِ وَمَا ذَرَيْنَ، أَسْأَلُكَ خَيْرَ هَذِهِ الْقَرْيَةِ، وَخَيْرَ\nأَهْلِهَا، وَخَيْرَ مَا فِيهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ أَهْلِهَا، وَشَرِّ مَا فِيهَا)).", "oromo": "Yaa Allaah gooftaa samii torbaniifi waan isaan gaaddisiisanii,\n     gooftaa dachii torbaniifi waan isaan baatanii, gooftaa shayxaanaafi\n     waan isaan jallisanii, gooftaa qilleensaafi waan inni faffacaasee!\n     Toltuu magaalaa kanaa, toltuu jiraattota isheefi toltuu ishee\n     keessa jirun si kadha. Hamtuu ishee, hamtuu jiraattota isheefi\n     hamtuu ishee keessa jiru irraa sittin maganfadha.”"}]}, {"num": 98, "arabicTitle": "دُعاءُ دُخُولِ السُّوقِ", "oromoTitle": "Du’aa’ii yeroo gabaa (magaalaa) seenanii", "duas": [{"arabic": "(لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ،\nوَهُوَ حَيٌّ لاِ يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)).", "oromo": "Dhugaan gabbaramaan Rabbiin malee hin jiru. Inni tokkicha hiriyaa\n     hin qabneedha. Mootummaan kan isaati. Faaruunis kan Isaati. Inni ni\n     jiraachisa ni ajjeesa. Inni jiraataa hin duuneedha. Toltuun harka\n     isaa jira. Inni waan hunda irratti danda’aadha.”"}]}, {"num": 99, "arabicTitle": "الدُّعَاءُ إِذَا تَعِسَ المَرْكُوبُ", "oromoTitle": "Du’aa’ii nama geejjibni duraa dadhabee.", "duas": [{"arabic": "(بِسْمِ اللَّهِ)).", "oromo": "Maqaa Rabbiitiin.”"}]}, {"num": 100, "arabicTitle": "دُعَاءُ المُسَافِرِ لِلْمُقيم", "oromoTitle": "Du’aa’ii musaafirri nama biyyaatiif godhu", "duas": [{"arabic": "(أَسْتَوْدِعُكُمُ اللَّهَ الَّذِي لاَ تَضِيعُ وَدَائِعُهُ)).", "oromo": "Rabbii isa amaanaan biratti hin bannettin amaanaa isin kenna.”"}]}, {"num": 101, "arabicTitle": "دُعَاءُ المُقِيمِ لِلْمُسَافِرِ", "oromoTitle": "Du’aa’ii namni biyyaa musaafiraaf godhu", "duas": [{"arabic": "أَسْتَوْدِعُ اللَّهَ دِينَكَ، وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ)).", "oromo": "Amantii kee, amaanaa keetiifi dhuma hojii keetii Rabbittin amaanaa\n     kenna.”"}, {"arabic": "((زَوَّدَكَ اللَّهُ التَّقْوَى، وَغَفَرَ ذَنْبَكَ، وَيَسَّرَ لَكَ الخَيْرَ حَيْثُ ما\nكُنْتَ)).", "oromo": "Rabbiin taqwaa galaa siif haa godhu. Badii kee siif haa araaramu.\n     Bakka jirtu hundatti toltuu siif haa laaffisu.”"}]}, {"num": 102, "arabicTitle": "التَّكبيرُ والتَّسبِيحُ في سَيْرِ السَّفَر", "oromoTitle": "Adeemsa imalaa keessatti takbiiraafi tasbiiha gochuu", "duas": [{"arabic": "قَالَ جَابِرٌ : ((كُنَّا إِذَا صَعَدْنَا كَبَّرْنَا، وَإِذَا نَزَلْنَا سَبَّحْنَا)).", "oromo": "Jaabir (ra) ni jedhe: “yeroo gaaratti ol baane takbiiraa jenna.\n     Yeroo buune immoo tasbiiha goona.”"}]}, {"num": 103, "arabicTitle": "دُعاءُ المُسَافِرِ إِذَا أَسْحَرَ", "oromoTitle": "Du’aa’ii musaafirri yeroo assuhrii godhu", "duas": [{"arabic": "(سَمَّعَ سَامِعٌ بِحَمْدِ اللَّهِ، وَحُسْنِ بَلاَئِهِ عَلَيْنَا، رَبَّنَا صاحِبْنَا، وَأَفْضِلْ عَلَيْنَا،\nعَائِذاً بِاللَّهِ مِنَ النَّارِ)).", "oromo": "Faaruu nuti Rabbiin faarsinuufi ni’imaa isaa gaarii nurra jiru\n     amanuu dhagahaan dhagahee [ragaa baha]. Yaa Rabbii keenya nuun\n     saahiboomi. Tola kee nurratti dhangalaasi. Ibidda irraa Rabbittin\n     maganfadha.”"}]}, {"num": 104, "arabicTitle": "الدُّعَاءُ إِذَا نَزَلَ مَنْزِلاً فِي سَفَرٍ أَوْ غَيْرِهِ", "oromoTitle": "Du’aa’ii yeroo imala yookiin kan biroo keessatti qubatte gootu", "duas": [{"arabic": "(أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ)).", "oromo": "Hamtuu Rabbiin uume irraa jecha Rabbii guutuuttin maganfadha.”"}]}, {"num": 105, "arabicTitle": "ذِكْرُ الرُّجُوعِ مِنَ السَّفَرِ", "oromoTitle": "Zikrii yeroo imalaa deebi’anuu", "duas": [{"arabic": "(يُكَبِّرُ عَلَى كُلِّ شَرَفٍ ثَلاَثَ تَكْبِيرَاتٍ ثُمَّ يَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ\nشَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، آيِبُونَ، تَائِبُونَ،\nعَابِدُونَ، لِرَبِّنا حَامِدُونَ، صَدَقَ اللَّهُ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزابَ\nوَحْدَهُ)).", "oromo": "Gaara hundarratti takbiiraa sadii jedha. Ergasii ni jedha: “Dhugaan\n     gabbaramaan Rabbiin malee hin jiru. Inni tokkicha hiriyaa hin\n     qabneedha. Mootummaan kan isaati. Faaruunis kan Isaati. Inni waan\n     hunda irratti danda’aadha. Nuti deebi’oodha; yoo Rabbiin fedhe\n     toobbataa, Rabbiin gabbaraa, Rabbii keenya faarsaadha. Rabbiin\n     waadaa isaa dhugoomseera. Gabricha isaa tumseera. Kophaa isaa garee\n     diinaa bittinneesseera.”"}]}, {"num": 106, "arabicTitle": "مَا يَقُولُ مَنْ أَتَاهُ أَمْرٌ يَسُرُّهُ أَوْ يَكْرَهُهُ", "oromoTitle": "Waan namni dhimmi isa gammachiisu yookiin jibbisiisu mudate jedhu", "duas": [{"arabic": "(كَانَ النَّبِيُّ ص إِذَا أَتَاهُ الْأَمْرُ يَسُرُّهُ قَالَ: ((الْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ\nالصَّالِحَاتُ)) وَإِذَا أَتَاهُ الْأَمْرُ يَكْرَهُهُ قَالَ: ((الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ)).", "oromo": "Nabiyyiin (saw) yeroo dhimmi isaan gammachiisu isaan mudate ni\n     jedhu: “faaruun kan Rabbii ni’imaa isaatiin wanti gaggaariin\n     guuttuuti.” Yeroo wanti isaan jibban isaan mudate immoo “haala\n     hundarrattuu faaruun kan Rabbiiti” jedhu."}]}, {"num": 107, "arabicTitle": "فَضْلُ الصَّلاَةِ عَلَى النَّبيِّ", "oromoTitle": "Sadarkaa Nabiyyii (saw) irratti salawaata buusuun qabu", "duas": [{"arabic": "قَالَ النَّبِيُّ : ((مَنْ صَلَّى عَلَيَّ صَلاَةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْراً)).", "oromo": "Nama si’a tokko salawaata narratti buuse Rabbiin isheedhaan si’a\n     kudhan rahmata isarratti buusa.”"}, {"arabic": "وَقَالَ : ((لاَ تَجْعَلُوا قَبْرِي عِيداً وَصَلُّوا عَلَيَّ؛ فَإِنَّ صَلاَتَكُم تَبْلُغُنِي حَيْثُ\nكُنْتُمْ)).", "oromo": "Nabiyyiin (saw) ni jedhan: “awwaala kiyya iida hin taasisinaa.\n     Rahmata narratti buusaa. Salawaanni keessan bakkuma isin jirtan\n     irraa natti dhaqqaba. “"}, {"arabic": "وَقَالَ : ((الْبَخِيلُ مَنْ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ)).", "oromo": "Doyna namaa jechuun nama ani biratti dubbatamee salawaata narratti\n     hin buufneedha.”"}, {"arabic": "وَقَالَ :((إِنَّ لِلَّهِ مَلاَئِكَةً سَيَّاحِينَ فِي الْأَرْضِ يُبَلِّغُونِي مِنْ أُمَّتِي\nالسَّلاَمَ)).", "oromo": "Nabiyyiin (saw) ni jedhan: “Rabbiin maleykota dachii keessa deeman\n     kan salaamtaa ummata kiyyaa natti dhaqqabsiisan qaba.”"}, {"arabic": "((وَقَالَ : ((مَا مِنْ أَحَدٍ يُسَلِّمُ عَلَيَّ إِلاَّ رَدَّ اللَّهُ عَلَيَّ رُوحِيَ حَتَّى أَرُدَّ عَلَيْهِ\nالسَّلاَمَ)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “namni tokko salaamtaa naan jedhee\n     yoo Rabbiin ruuhii kiyya natti deebisee salaamtaa isatti deebise\n     malee hin hafu.”"}]}, {"num": 108, "arabicTitle": "إِفْشَـــــاءُ السَّــــــــلاَمِ", "oromoTitle": "Salaamtaa babal’isuu", "duas": [{"arabic": "قَالَ رَسُولُ اللَّهِ : ((لاَ تَدْخُلُوا الْجَنَّةَ حَتَّى تُؤْمِنُوا، وَلاَ تُؤْمِنُوا حَتَّى\nتَحَابُّوا، أَوَلاَ أَدُلُّكُم عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُم، أَفْشُوا السَّلاَمَ\nبَيْنَكُمْ)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “hanga amantanutti jannata hin\n     seentanu. Hanga wal jaalattanitti hin amantanu. Waan isin\n     hojjattanii wal jaalattan isin akeekuu? Salaamtaa jidduu\n     keessanitti babal’isaa.”"}, {"arabic": "((ثَلاَثٌ مَنْ جَمَعَهُنَّ فَقَدْ جَمَعَ الْإِيمَانَ: الْإِنْصَافُ مِنْ نَفْسِكَ، وَبَذْلُ السَّلاَمِ\nلِلْعَالَمِ، وَالْإِنْفَاقُ مِنَ الإِقْتَارِ)).", "oromo": "“Namni waa sadii walitti qabate dhugumatti iimaana walitti\n     qabateera: lubbuu kee irratti haqa hojjachuu, aalamaaf salaamtaa\n     baay’isuufi hiyyummaa irraa kennachuudha.”"}, {"arabic": "وَعَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَجُلاً سَأَلَ النَّبِيَّ ص أَيُّ\nالْإِسْلاَمِ خَيْرٌ قَالَ: ((تُطْعِمُ الطَّعَامَ، وَتَقْرأُ السَّلاَمَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ\nتَعْرِفْ)).", "oromo": "Abdullaah bin Umar irraa odeeffamee (ra) ni jedhe: namichi tokko\n     Islaama kamtu caala jedhee Nabiyyii (saw) gaafate. Nabiyyiin (saw)\n     ni jedhan: “nyaata nyaachifta. Nama beektuufi hin beekne irratti\n     salaamtaa qaraata.”"}]}, {"num": 109, "arabicTitle": "كَيْفَ يَرُدُّ السَّلاَمَ عَلَى الْكَافِرِ إِذَا سَلَّمَ", "oromoTitle": "Yeroo kaafirri salaamtaa jedhe akkaataa ittiin deebisan", "duas": [{"arabic": "(إذَا سَلَّمَ عَلَيْكُمْ أَهْلُ الْكِتَابِ فَقُولُوا: وَعَلَيْكُمْ)).", "oromo": "Yeroo warreen kitaabaa salaamtaa isiniin jedhan “isin irras haa\n     jiraatu” jedhaa."}]}, {"num": 110, "arabicTitle": "الدُّعاءُ عِنْدَ سَمَاعِ صِياحِ الدِّيكِ ونَهِيقِ الْحِمَارِ", "oromoTitle": "Du’aa’ii yeroo lukkuun iyyeefi harreen halaake godhamu", "duas": [{"arabic": "(إِذَا سَمِعْتُمْ صِيَاحَ الدِّيَكَةِ فَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ؛ فَإِنَّهَا رَأَتْ مَلَكاً وَإِذَا\nسَمِعْتُمْ نَهِيقَ الْحِمَارِ فَتَعَوَّذُوا بِاللَّهِ مِنَ الشَّيطَانِ؛ فَإِنَّهُ رَأَى شَيْطَاناً)).", "oromo": "Yeroo iyya lukkuu dhageessan tola Rabbii isa kadhaa. Isheen\n     maleykaa argite waan taateef. Yeroo halaaka harree dhageessan\n     shayxaana irraa Rabbitti maganfadhaa. Inni shayxaana arge waan\n     ta’eef."}]}, {"num": 111, "arabicTitle": "الدُّعَاءُ عِنْدَ سَمَاعِ نُبَاحِ الْكِلاَبِ بِاللَّيْلِ", "oromoTitle": "Du’aa’ii halkan yeroo sareen dutte godhamu", "duas": [{"arabic": "(إِذَا سَمِعْتُمْ نُبَاحَ الْكِلاَبِ وَنَهِيقَ الْحَمِيرِ بِاللَّيْلِ فَتَعَوَّذُوا بِاللَّهِ مِنْهُنَّ؛\nفَإِنَّهُنَّ يَرَيْنَ مَا لاَ تَرَوْنَ)).", "oromo": "Yeroo halkan dutaa sareefi halaaka harree dhageessan isaan irraa\n     Rabbitti maganfadhaa. Isaan waan isin hin argine argu.”"}]}, {"num": 112, "arabicTitle": "الدُّعَاءُ لِمَنْ سَبَبْتَه", "oromoTitle": "Du’aa’ii nama arrabsiteef gootu", "duas": [{"arabic": "قَالَ النَّبِيُّ ص: ((اللَّهُمَّ فَأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ\nالْقِيَامَةِ)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “yaa Rabbi mu’umina ani arrabse\n     hundaawuu arraba sana Guyyaa Qiyaamaa si biratti dhiheenya\n     taasisiif.”"}]}, {"num": 113, "arabicTitle": "مَا يَقُولُ المُسْلِمُ إِذَا مَدَحَ المُسْلِمَ", "oromoTitle": "Waan Muslimni yeroo Muslima faarse jedhu", "duas": [{"arabic": "قَالَ النَّبِيُّ : ((إِذَا كَانَ أَحَدُكُم مَادِحاً صَاحِبَهُ لاَ مَحَالَةَ فَلْيَقُلْ: أَحْسِبُ فُلاَناً\nوَاللَّهُ حَسِيبُهُ، وَلاَ أُزَكِّي عَلَى اللَّهِ أَحَداً، أَحْسِبُهُ – إِنْ كَانَ يَعْلَمُ ذَاكَ – كَذَا\nوَكَذَا)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “tokkoon keessan yeroo hiriyaa\n     isaa faarsuun dirqama itti ta’e ‘abalu akkanaan yaada; garuu\n     Rabbitu isa qormaata. Nama tokkollee Rabbirratti hin qulqulleessu.\n     Yoo waan irraa beeku ta’eef akkana akkana ta’aan yaada’ haa\n     jedhu.”"}]}, {"num": 114, "arabicTitle": "مَا يَقُولُ المُسْلِمُ إِذَا زُكِّيَ", "oromoTitle": "Waan Muslimni ogga qulqulleeffame jedhu", "duas": [{"arabic": "(اللَّهُمَّ لاَ تُؤَاخِذْنِي بِمَا يَقُولُونَ، وَاغْفِرْ لِي مَا لاَ يَعْلَمُونَ، [وَاجْعَلْنِي خَيْراً\nمِمَّا يَظُّنُّونَ])).", "oromo": "Yaa Rabbi waan isaan jedhaaranuun na hin qabin. Waan isaan hin\n     beekne naaf araarami. Waan isaan yaadaaran irra gaarii na\n     taasisi.”"}]}, {"num": 115, "arabicTitle": "كَيْفَ يُلَبِّي المُحْرِمُ فِي الْحَجِّ أَوِ الْعُمْرَةِ", "oromoTitle": "Muhrimni hajjiifi umraa keessatti akkamiin talbiyaa jedha", "duas": [{"arabic": "(لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ، وَالنِّعْمَةَ، لَكَ\nوَالْمُلْكَ، لاَ شَرِيكَ لَكَ)).", "oromo": "Siif owwaadhe yaa Rabbi siif owwaadhe! Shariikni siif hin jiruu\n     siif owwaadhe. Faaruun, qananiifi mootummaan kan keeti. Shariikni\n     siif hin jiru.\""}]}, {"num": 116, "arabicTitle": "التَّكْبِيرُ إِذَا أَتَى الْحَجَرَ الأَسْوَدَ", "oromoTitle": "Takbiiraa yeroo rukn al-aswaditti dhufanii", "duas": [{"arabic": "(طَافَ النَّبيُّ بِالْبَيْتِ عَلَى بَعِيرٍ كُلَّمَا أَتَى الرُّكْنَ أَشَارَ إِلَيْهِ بِشَيْءٍ عِنْدَهُ\nوَكَبَّرَ)).", "oromo": "Nabiyyiin (saw) gaala irra taa’anii ka’abaa irra naanna’an. Hanguma\n     ruknal aswaditti dhufanuun, wahiin itti akeekanii takbiiraa\n     godhu."}]}, {"num": 117, "arabicTitle": "الدُّعَاءُ بَيْنَ الرُّكْنِ الْيَمَانِيِّ وَالْحَجَرِ الأَسْوَدِ", "oromoTitle": "Du’aa’ii jidduu Rukn Alyamaaniifi Hajar Al-aswaditti godhamu", "duas": [{"arabic": "(﴿رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ\nالنَّارِ﴾)).", "oromo": "Gooftaa keenya! addunyaatti toltuu, Aakhirattis toltuu nuuf kenni;\n     adabbii ibiddaa irraa nu baraari.\""}]}, {"num": 118, "arabicTitle": "دُعَاءُ الْوُقُوفِ عَلَى الصَّفَا وَالمَرْوَةِ", "oromoTitle": "Du’aa’ii Safaafi Marwaa irratti godhamu", "duas": [{"arabic": "(لَمَّا دَنَا النَّبِيُّ مِنَ الصَّفَا قَرَأَ: ﴿ نَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ فَمَنْ\nحَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا وَمَنْ تَطَوَّعَ خَيْرًا فَإِنَّ اللَّهَ شَاكِرٌ\nعَلِيمٌ}.. }البقرة : 158{ ))أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ)) فَبَدَأَ بِالصَّفَا فَرَقِيَ عَلَيْهِ\nحَتَّى رَأَى الْبَيْتَ، فَاسْتَقْبَلَ الْقِبْلَةَ، فَوَحَّدَ اللَّهَ وَكبَّرَهُ وَقَالَ: ((لاَ إِلَهَ إِلاَّ اللَّهُ\nوَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لاَ إِلَهَ إِلاَّ اللَّهُ\nوَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ، ثُمَّ دَعَا بَيْنَ ذلكَ. قَالَ مِثْلَ\nهَذَا ثَلاَثَ مَرَّاتٍ)) الْحَدِيثُ. وَفِيهِ: ((فَفَعَلَ عَلَى الْمَرْوَةِ كَمَا فَعَلَ عَلَى\nالصَّفَا)).", "oromo": "Nabiyyiin (saw) yeroma Safaatti dhihaatanu \"[gaarri] Safaafi Marwaa\n     mallattoolee Rabbii irraayi\" jechuu qara'an. \"Waan Rabbiin\n     jalqabeenin jalqaba\" jedhan. Safaatti ol ba'anii Manicha (ka'abaa)\n     argan. Qiblaatti gara galanii Rabbiin tokkoomsanii isa guddisan. Ni\n     jedhan: \"Laa Ilaaha Illallaah; Wahdahuu laa shariika lah. Lahul\n     mulk, walahul hamdu wahuwa alaa kulli shay'iin qadiir. Laa'ilaaha\n     illallaahu wahdah, anjaza wa'adah; wa nasara abdah. Wahazamal\n     ahzaaba wahdah\" hiikti isaas \"Dhugaan gabbaramaan Rabbiin malee hin\n     jiru; inni tokkicha. Shariikni isaaf hin jiru. Mootummaan kan\n     isaati; faaruunis kan isaati. Inni waan cufa irratti danda'aadha.\n     Dhugaan gabbaramaan Rabbiin malee hin jiru. Beellama isaa ni guute;\n     garbicha isaas ni tumse; garee diinotaas kophaa isaa bittinneesse.\"\n     Ergasii jidduu sanatti du'aa'ii godhanii fakkiidhuma isa kanaa\n     yeroo sadii jedhan. Ergasii Safaa irraa gara Marwaatti bu'an.\n     Yeroma miilli isaanii garaa dhiibuu keessa gadi dhaabbatu ni\n     fiigan. Yeroo ol koran immoo gara Marwaa deeman. Marwaa irrattis\n     fakkiidhuma waan Safaa irratti hojjatanii hojjatan.\""}]}, {"num": 119, "arabicTitle": "الدُّعَاءُ يَوْمَ عَرَفَةَ", "oromoTitle": "Du’aa’ii guyyaa Arafaa", "duas": [{"arabic": "قَالَ النَّبِيُّ : ((خَيْرُ الدُّعَاءِ دُعَاءُ يَوْمِ عَرَفَةَ، وَخَيْرُ مَا قُلْتُ أَنَا وَالنَّبيُّونَ مِنْ\nقَبْلِي: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ\nقَدِيرٌ)).", "oromo": "Caalaan du’aa’ii, du’aa’ii guyyaa Arafaati. Caalaan waan aniifi\n     nabiyyoonni ana duraa jedhanii \"Dhugaan gabbaramaan Rabbiin malee\n     hin jiru; inni tokkicha. Shariikni isaaf hin jiru. Mootummaan kan\n     isaati; faaruunis kan isaati. Inni waan cufa irratti\n     danda'aadha.”"}]}, {"num": 120, "arabicTitle": "الذِّكْرُ عِنْدَ المَشْعَرِ الْحَرَامِ", "oromoTitle": "Zikrii Mash’ar Alharaam biratti godhamu", "duas": [{"arabic": "(رَكِبَ النَّبِيُّ الْقَصْوَاءَ حَتَّى أَتَى الْمَشْعَرَ الْحَرَامَ فَاسْتَقْبَلَ الْقِبْلَةَ (فَدَعَاهُ،\nوَكَبَّرَهُ، وَهَللَّهُ، وَوَحَّدَهُ) فَلَمْ يَزَلْ وَاقِفاً حَتَّى أَسْفَرَ جِدَّاً فَدَفَعَ قَبْلَ أَنْ تَطْلُعَ\nالشَّمسُ)).", "oromo": "Nabiyyiin (saw) geejjiba yaabbatanii mash'aral Haraamiin dhufanii\n     qiblaatti deebi'uun du'aa godhan; Rabbiin guddisan. Laa Ilaaha\n     Illallaah jedhan. Isa tokkichoomsan. Hanga bareechee ifutti achi\n     dhaabatan. Achumaan odoo biiftuun hin bahin deeman."}]}, {"num": 121, "arabicTitle": "التَّكْبِيرُ عِنْدَ رَمْي ِ الْجِمَارِ مَعَ كُلِّ حَصَاةٍ", "oromoTitle": "Yeroo jamraa darbatan takbiiraan shafee hunda waliin jedhama", "duas": [{"arabic": "(يُكَبِّرُ كُلَّمَا رَمَى بِحَصَاةٍ عِنْدَ الْجِمَارِ الثَّلاَثِ، ثُمَّ يَتَقَدَّمُ، ويَقِفُ يَدْعُو مُسْتَقْبِلَ\nالْقِبلَةِ، رَافِعاً يَدَيْهِ بَعْدَ الْجَمْرَةِ الْأُولَى وَالثَّانِيَةِ. أَمَّا جَمْرَةُ الْعَقَبَةِ فَيَرْمِيهَا\nوَيُكَبِّرُ عِنْدَ كُلِّ حَصَاةٍ وَيَنْصَرِفُ وَلاَ يَقِفُ عِنْدَهَا)).", "oromo": "Jamraa sadan birattuu hanguma shafee darbatuun takbiiraa godha.\n     Jamraa tokkoffaafi lammaffaa booda gara fuulduraa deemee qiblaatti\n     deebi’ee harka isaa ol fuudhee du’aa’ii godha. Jamrat Al-aqabaa\n     biratti immoo ishee darbatee shafee hunda biratti takbiiraa jedha.\n     Ergasii ni deema dhaabatee du’aa’ii hin godhu.”"}]}, {"num": 122, "arabicTitle": "دُعَاءُ التَّعَجُّبِ وَالأَمْرِ السَّارِّ", "oromoTitle": "Du’aa’ii nama waa ajaa’ibsiifateefi wahitti gammadee", "duas": [{"arabic": "((سُبْحَانَ اللَّهِ!)).", "oromo": "Rabbiin qulqullaa’e!”"}, {"arabic": "((اللَّهُ أَكْبَرُ!)).", "oromo": "Rabbiin hundarra guddaadha.”"}]}, {"num": 123, "arabicTitle": "مَا يَفْعَلُ مَنْ أَتَاهُ أَمْرٌ يَسُرُّه", "oromoTitle": "Waan namni dhimmi isa gammachiisu itti dhufe hojjatu", "duas": [{"arabic": "(كَانَ النَّبيُّ ص إِذَا أَتَاهُ أَمْرٌ يَسُرُّهُ أَوْ يُسَرُّ بِهِ خَرَّ سَاجِداً شُكْراً لِلَّهِ تَبَارَكَ\nوَتَعَالَى)).", "oromo": "Nabiyyiin (saw) yeroo dhimmi isaan gammachiisu yookiin itti\n     gammadamu isaanitti dhufe galata Rabbii guddatee ol ta’eetiif\n     sujuudii bu’u turan.”"}]}, {"num": 124, "arabicTitle": "مَا يَفْعَلُ وَيَقُولُ مَنْ أَحَسَّ وَجَعاً فِي جَسَدِهِ", "oromoTitle": "Waan namni dhukkubni qaama isaatti dhaga’ame jedhu", "duas": [{"arabic": "(ضَعْ يَدَكَ عَلَى الَّذِي تَألَّمَ مِنْ جَسَدِكَ وَقُلْ: بِسْمِ اللَّهِ، ثَلاَثاً، وَقُلْ سَبْعَ مَرَّاتٍ:\nأَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ)).", "oromo": "Qaama kee isa laalate irra harka kee kaa’ii si’a sadii “maqaa\n     Rabbiitiin” jedhi. Ergasii si’a torba kan armaan gadii jedhi:\n     “hamtuu natti dhaga’amaaruufi sodaadhu irraa Rabbiifi dandeettii\n     isaattin maganfadha.”"}]}, {"num": 125, "arabicTitle": "دُعَاءُ مَنْ خَشِيَ أَنْ يُصِيبَ شَيْئاً بِعَيْنِهِ", "oromoTitle": "Du’aa’ii namni ija isaatiin waa tuquu sodaate godhu", "duas": [{"arabic": "(إِذَا رَأَى أَحَدُكُم مِنْ أَخِيهِ، أَوْ مِنْ نَفْسِهِ، أَوْ مِنْ مَالِهِ مَا يُعْجِبُهُ [فَلْيَدْعُ لَهُ\nبِالْبَرَكَةِ] فَإِنَّ الْعَيْنَ حَقٌّ)).", "oromo": "Tokkoon keessan yeroo obboleessa isaa, lubbuu isaa yookiin qabeenya\n     isaa irraa waan isa ajaa’ibsiise arge barakaa haa kadhatuuf. Ijji\n     (budaan) dhugaadha.”"}]}, {"num": 126, "arabicTitle": "مَا يُقَالُ عِنْدَ الْفَزَعِ", "oromoTitle": "Waan yeroo naasuu jedhamu", "duas": [{"arabic": "(لاَ إِلَهَ إِلاَّ اللَّهُ!)).", "oromo": "Dhugaan gabbaramaan Rabbiin malee hin jiru.”"}]}, {"num": 127, "arabicTitle": "مَا يَقُولُ عِنْدَ الذَّبْحِ أَوِ النَّحْرِ", "oromoTitle": "Waan yeroo gorraasuu jedhamu", "duas": [{"arabic": "(بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ [اللَّهُمَّ مِنْكَ وَلَكَ] اللَّهُمَّ تَقَبَّلْ مِنِّي))", "oromo": "Maqaa Rabbiitiin; Rabbiin hundarra guddaadha. Yaa Rabbi si biraayyi\n     simaafin qalaaras. Yaa Rabbi narraa qeebali."}]}, {"num": 128, "arabicTitle": "مَا يَقُولُ لِرَدِّ كَيْدِ مَرَدَةِ الشَّيَاطِينِ", "oromoTitle": "Toftaa shayxaana fincilaa deebisuuf waan jedhamu", "duas": [{"arabic": "(أَعُوذُ بكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لاَ يُجَاوِزُهُنَّ بَرٌّ وَلاَ فَاجِرٌ: مِنْ شَرِّ مَا\nخَلَقَ، وَبَرَأَ وَذَرَأَ، وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ، وَمِنْ شَرِّ مَا يَعْرُجُ فيهَا، وَمِنْ شَرِّ مَا\nذَرَأَ فِي الْأَرْضِ، وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ، وَمِنْ شَرِّ كُلِّ\nطَارِقٍ إِلاَّ طَارِقاً يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ)).", "oromo": "Hamtuu Rabbiin uume, khallaqeefi facaase irraa, hamtuu samii\n     bu’uufi hamtuu ol koru irraa, hamtuu inni dachii keessa facaaseefi\n     hamtuu ishee irraa bahu irraa, hamtuu mokkoroo guyyaafi halkanii\n     irraa, hamtuu waan halkan dhufuu kan khayriin hin dhufnee irraa\n     jechoolee Rabbii guutuu kan warri gaggaariifi hamaanillee bira hin\n     tarreenin maganfadha yaa Rahmaan.”"}]}, {"num": 129, "arabicTitle": "الاستِغْفَارُ والتَّوبَةُ", "oromoTitle": "Araarama kadhachuufi tawbachuu", "duas": [{"arabic": "قَالَ رَسُولُ اللَّهِ ص: ((وَاللَّهِ إِنِّي لأَسْتَغفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فِي الْيَوْمِ\nأَكْثَرَ مِنْ سَبْعِينَ مَرَّةٍ)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “wallaahii ani guyyaa tokko\n     keessatti si’a torbaatamaa olin araarama Rabbiin kadhee tawbaa gara\n     isaatti deebi’a.”"}, {"arabic": "وَقَالَ : ((يَا أَيُّهَا النَّاسُ تُوبُوا إِلَى اللَّهِ فَإِنِّي أَتُوبُ فِي الْيَوْمِ إِلَيْهِ\nمِائَةَ مَرَّةٍ)).", "oromo": "Nabiyyiin (saw) ni jedhan: “yaa namootaa tawbaa godhaa gara Rabbii\n     deebi’aa. Ani guyyaa tokko keessatti si’a dhibban tawbadha.”"}, {"arabic": "وَقَالَ : ((مَنْ قَالَ أَسْتَغْفِرُ اللَّهَ الْعَظيمَ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ\nالقَيّوُمُ وَأَتُوبُ إِلَيهِ، غَفَرَ اللَّهُ لَهُ وَإِنْ كَانَ فَرَّ مِنَ الزَّحْفِ)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “namni ‘Rabbii guddaa isa dhugaan\n     gabbaramaan isa malee hin jirre, jiraataa, waan hunda to’ataan\n     araarama kadha; tawbadheen gara isa deebi’a’ jedhe, odoma lola\n     irraa baqateera ta’ee Rabbiin isaaf araarama.”"}, {"arabic": "وَقَالَ : ((أَقْرَبُ مَا يَكُونُ الرَّبُّ مِنَ الْعَبْدِ فِي جَوْفِ اللَّيْلِ الآخِرِ فَإِنِ\nاسْتَطَعْتَ أَنْ تَكُونَ مِمَّنْ يَذْكُرُ اللَّهَ فِي تِلْكَ السَّاعَةِ فَكُنْ)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “yeroon Rabbiin akkaan gabrichatti\n     dhihaatu dhuma halkanii keessa. Yoo nama yeroo sana keessa Rabbiin\n     faarsuu danda’u taateef isaan irraa ta’i.”"}, {"arabic": "وَقَالَ : ((أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ فَأَكثِرُوا\nالدُّعَاءَ)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “yeroon gabrichi akkaan Rabbii\n     isaatti dhihaatu ogga sujuudiiti. Kanaafuu du’aa’ii\n     baay’isaa.”"}, {"arabic": "وَقَالَ : ((إِنَّهُ لَيُغَانُ عَلَى قَلْبِي وَإنِّي لأَسْتَغْفِرُ اللَّهَ فِي الْيَوْمِ مِائَةَ\nمَرَّةٍ)).", "oromo": "Nabiyyiin (saw) ni jedhan: “yeroo garii qalbii kiyya irra haguuga.\n     Ani guyyaa keessatti si’a dhibban Rabbiin araarama kadha.”"}]}, {"num": 130, "arabicTitle": "فَضْلُ التَّسْبِيحِ وَالتَّحْمِيدِ، وَالتَّهْلِيلِ، وَالتَّكْبِيرِ", "oromoTitle": "Sadarkaa tasbiihiin, Rabbiin faarsuun, tahliilliifi takbiiraan qabu[562]", "duas": [{"arabic": "((قَالَ مَنْ قَالَ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ وَلَوْ\nكَانَتْ مِثْلَ زَبَدِ الْبَحْر)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “namni guyyaatti si’a dhibba\n     “faaruu isaa waliin Rabbiin qulqullaa’e” jedhe badiin isaa odoma\n     fakkii oomocha bahrii ta’eeyyuu irraa harca’a.”"}, {"arabic": "وَقَالَ : ((مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ\nالْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ عَشْرَ مِرَارٍ، كَانَ كَمَنْ أَعْتَقَ أَرْبَعَةَ أَنْفُسٍ مِنْ وَلَدِ\nإِسْمَاعِيلَ)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “namni si’a kudhan ‘dhugaan\n     gabbaramaan Rabbiin malee hin jiru. Inni tokkicha. Shariikni isaaf\n     hin jiru. Mootummaan kan isaati; faaruunis kan isaati. Inni waan\n     cufa irratti danda'aadha’ jedhe akka nama ilmaan Ismaa’iil irraa\n     nama kudhan bilisoomsee ta’a.”"}, {"arabic": "وَقَالَ : ((كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ\nإِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحانَ اللَّهِ الْعَظِيمِ)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “himoonni lama arraba irratti\n     sasalphoo, madaala keessatti gurguddoo, gara Arrahmaanitti\n     jaallatamtuun ‘Rabbiin faaruu isaa waliin qulqullaa’e. Rabbiin\n     guddaan qulqullaa’e’ kan jedhuudha.”"}, {"arabic": "وَقَالَ : ((لَأَنْ أَقُولَ سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ،\n     وَاللَّهُ أَكْبَرُ، أَحَبُّ إِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمسُ)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “ani ‘Rabbiin qulqullaa’e; faaruun\n     kan Rabbiiti. Dhugaan gabbaramaan Rabbiin malee hin jiru. Rabbiin\n     hundarra guddaadha’ jechuutu waan biiftuun irratti baate irra na\n     biratti jaalatama.”"}, {"arabic": "وَقَالَ : ((أَيَعْجِزُ أَحَدُكُم أَنْ يَكْسِبَ كُلَّ يَوْمٍ أَلْفَ حَسَنَةٍ)) فَسَأَلَهُ سَائِلٌ\n     مِنْ جُلَسَائِهِ كَيْفَ يَكْسِبُ أَحَدُنَا أَلْفَ حَسَنَةٍ؟ قَالَ: ((يُسَبِّحُ مِائَةَ تَسْبِيحَةٍ، فَيُكتَبُ\n     لَهُ أَلْفُ حَسَنَةٍ أَوْ يُحَطُّ عَنْهُ أَلْفُ خَطِيئَةٍ)).", "oromo": "Nabiyyiin (saw) ni jedhan: “tokkoon keessan guyyaa hundaa toltuu\n     kuma hojjachuu dadhabaa?” Namni tokko “tokkoon keenya akkamitti\n     toltuu kuma hojjachuu danda’a?” jedhe. Nabiyyiin (saw) ni jedhan:\n     “tasbiihaa dhibba jedha. Kanaan toltuun kumni isaaf barreeffama\n     yookiin badiin kumni isarraa harcaafama.”"}, {"arabic": "((مَنْ قَالَ: سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ غُرِسَتْ لَهُ نَخْلَةٌ فِي\nالْجَنَّةِ)).", "oromo": "Nama “Rabbiin guddaan faaruu isaa waliin qulqullaa’e” jedhe,\n     jannata keessatti nakhliin isaaf dhaabamti."}, {"arabic": "وَقَالَ : ((يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ أَلاَ أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ))؟\nفَقُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: ((قُلْ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)).", "oromo": "Ergamaan Rabbii (saw) ni jedhan: “Yaa Abdullaah bin Qays kuusaa\n     kuusaalee jannataa irraa ta’e si akeekuu?” Eeyyeen yaa Ergamaa\n     Rabbiin jedhe. Nabiyyiin (saw) ni jedhan: “tooftaafi humni Rabbiin\n     biraa malee hin jiru’ jedhi.”"}, {"arabic": "وَقَالَ : ((أَحَبُّ الْكَلاَمِ إِلَى اللَّهِ أَرْبَعٌ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ\nإِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، لاَ يَضُرُّكَ بِأَيِّهِنَّ بَدَأتَ)).", "oromo": "Nabiyyiin (saw) ni jedhan: “haasaan Rabbiin biratti akkaan\n     jaallatamaan afuri: Rabbiin qulqullaa’e; faaruun kan Rabbiiti.\n     Dhugaan gabbaramaan Rabbiin malee hin jiru. Rabbiin hundarra\n     guddaadha.’ Isaan keessaa kamiinuu eegaltu si hin miidhu.”"}, {"arabic": "جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ فَقَالَ: عَلِّمْنِي كَلاماً أَقُولُهُ: قَالَ: ((قُلْ: لاَ\nإِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، اللَّهُ أَكْبَرُ كَبِيراً، وَالْحَمْدُ لِلَّهِ كَثِيراً، سُبْحَانَ\nاللَّهِ رَبِّ العَالَمِينَ، لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَزِيزِ الْحَكِيمِ)) قَالَ: فَهَؤُلاَءِ\nلِرَبِّي، فَمَا لِي؟ قَالَ: ((قُلْ: اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي،\nوَارْزُقْنِي)).", "oromo": "Namni baadiyyaa tokko gara Ergamaa Rabbii (saw) dhufee ni jedhe:\n     ‘jecha ani jedhu na barsiisi.’ Nabiyyiin (saw) ni jedhan: “\"Dhugaan\n     gabbaramaan Rabbiin malee hin jiru. Inni tokkicha. Shariikni isaaf\n     hin jiru. Rabbiin guddina isaan malu guddate. Faaruun baay’een kan\n     Rabbiiti. Rabbiin gooftaan aalamaa qulqullaa’e. Tooftaafi humni,\n     Rabbii injifataa ogeessa biraa malee hin argamu’ jedhi.” Namichis\n     “kuni Rabbii kootiifi. Anaahoo?” jedhe. Nabiyyiin (saw) ni jedhan:\n     “yaa Rabbi naaf araarami. Na mararfadhu. Na qajeelchi. Na soori”\n     jedhi."}, {"arabic": "كَانَ الرَّجُلُ إِذَا أَسْلَمَ عَلَّمَهُ النَّبيُّ الصَّلاَةَ ثُمَّ أَمَرَهُ أَنْ يَدْعُوَ بِهَؤُلاَءِ\nالْكَلِمَاتِ: ((اللَّهُمَّ اغْفِرِ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَعَافِنِي وَارْزُقْنِي)).", "oromo": "Namni tokko yeroo inni islaama’e Nabiyyiin (saw) salaata isa\n     barsiisu. Ergasii jechoota armaan gadiitiin kadhachuu isa barsiisu:\n     “yaa Rabbi naaf araarami. Na mararfadhu. Na qajeelchi. Nagaa na\n     godhi. Na soori.”"}, {"arabic": "((إِنَّ أَفْضَلَ الدُّعَاءِ الْحَمْدُ لِلَّهِ، وَأَفضَلَ الذِّكْرِ لاَ إِلَهَ إِلاَّ\nاللَّهُ)).", "oromo": "Caalaan du’aa’ii ‘faaruun kan Rabbiiti’ jechuu yoo ta’u zikriin\n     caalaan ‘dhugaan gabbaramaan Rabbiin malee hin jiru’ kan\n     jedhuudha.”"}, {"arabic": "((الْبَاقِيَاتُ الصَّالِحَاتُ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ،\nوَاللَّهُ أَكْبَرُ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)).", "oromo": "Jechooleen haftuun gaggaariin ‘Rabbiin qulqullaa’e. Faaruun kan\n     Rabbiiti. Dhugaan gabbaramaan Rabbiin malee hin jiru. Rabbiin\n     hundarra guddaadha. Tooftaafi humni Rabbiin biraa malee hin jiru”\n     kan jedhuudha"}]}, {"num": 131, "arabicTitle": "كَيْفَ كَانَ النَّبيُّ يُسَبِّحُ؟", "oromoTitle": "Nabiyyiin (saw) akkamitti tasbiiha godhu", "duas": [{"arabic": "عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: ((رَأَيْتُ النَّبيَّ يَعْقِدُ التَّسْبِيحَ))\nوفي زيادةٍ: ((بِيَمِينِهِ)).", "oromo": "Abdullaah bin Amr irraa odeeffamee (ra) ni jedhe: “kan Nabiyyiin\n     (saw) quba mirgaa isaaniitiin tasbiiha godhanin arge.”"}]}, {"num": 132, "arabicTitle": "مِنْ أَنْــــوَاعِ الْخَــــيْرِ وَالآدَابِ الْجَــــــامِعَةِ", "oromoTitle": "Gosoota toltuufi naamuusa walii gala", "duas": [{"arabic": "قَالَ النَّبِيُّ ((إِذَا كَانَ جُنْحُ اللَّيْلِ – أَوْ أَمْسَيْتُم – فَكُفُّوا صِبْيانَـكُم، فَإِنَّ\nالشَّيَاطِينَ تَنْتَشِرُ حِينَئِذٍ، فَإِذَا ذَهَبَ سَاعَةٌ مِنَ اللَّيلِ فَخَلُّوهُمْ، وَأَغْلِقُوا الأَبْوَابَ\nوَاذْكُرُوا اسْمَ اللَّهِ؛ فَإِنَّ الشَّيطَانَ لاَ يَفْتَحُ بَاباً مُغلَقاً، وَأَوْكُوا قِرَبَكُمْ، وَاذْكُرُوا\nاسْمَ اللَّهِ، وَخَمِّرُوا آنِيَتَكُم، وَاذْكُرُوا اسْمَ اللَّهِ، وَلَوْ أَنْ تَعْرُضُوا عَلَيْهَا شَيْئاً،\nوَأَطْفِئُوا مَصَابِيحَكُمْ)).", "oromo": "Yeroo sa’aatiin halkanii dhufe daa’imman keessan qabaa. Shayxaanni\n     yeroo kana keessa faffaca’u. Yeroo sa’aatiin halkanii hanga ta’e\n     deeme isaan lakkisaa. Hulaa cufaa. Maqaa Rabbii irratti dubbadhaa.\n     Shayxaanni hulaa cufame hin banu. Qalqalloo keessan hidhaatii maqaa\n     Rabbii irratti dubbadhaa. Meeshaa keessan odoma waan ta’e irra\n     fiduu ta’ee qadaadaatii maqaa Rabbii irratti dubbadhaa. Ifaa\n     keessanis dhaamsaa.”"}, {"arabic": "وَصَلَّى اللَّهُ وَسَلَّمَ وَبَارَكَ عَلَى نَبِيِّنَا مُحَمَّدٍ وَعَلَى آلِهِ وَأَصْحَابِهِ أَجْمَعِينَ.", "oromo": "Rahmanni Rabbii, nageenyi isaatiifi barakaan isaa Nabiyyii keenya\nMuhammad, maatii isaaniitiifi sahaabota isaanii hundarra haa jiraatu."}, {"arabic": "( المستطاب، ص 706.", "oromo": "Abuu Daawudtu gabaase. Albaaniin sahiiha godheera."}, {"arabic": "() مسلم، 4/ 1729، برقم 2203، من حديث عثمان بن أبي العاص ، وفيه\nففعلت ذلك، فأذهبه اللَّه عني.", "oromo": "Muslimtu hadiisa Usmaan bin Abil Aas keessatti gabaase. Hadiisicha\nkeessa kana raawwannaan woswaasiin narraa deeme jechuutu jira."}, {"arabic": "() رواه ابن حبان في صحيحه، برقم 2427 (موارد)، وابن السني، برقم\n351، وقال الحافظ: ((هذا حديث", "oromo": "Ibn Hibbaantu sahiiha isaa keessatti gabaase. Haafiz hadiisni kun\nsahiiha jedhe."}]}];

// --- Processinginginginginging logic ported from src/data/hisnul.ts ---
function isEmbeddedHeader(d) {
  var a = (d.arabic || '').trimStart();
  if (!a) return false;
  if (a.startsWith('(') || a.startsWith('\u00ab') || a.startsWith('"')) return false;
  return /\d+\s*[\u0640\-]+/.test(a);
}
function cleanArabicTitle(s) {
  return s.replace(/^\s*\d+\.?\s*\d*\s*[\u0640\-]+\s*/, '').trim();
}
function splitEmbeddedChapters(input) {
  var out = [];
  var queue = input.slice();
  while (queue.length) {
    var ch = queue.shift();
    var duas = ch.duas || [];
    var headerIdx = -1;
    for (var i = 0; i < duas.length; i++) {
      if (isEmbeddedHeader(duas[i])) { headerIdx = i; break; }
    }
    if (headerIdx === -1) { out.push(ch); continue; }
    var before = duas.slice(0, headerIdx);
    var header = duas[headerIdx];
    var after = duas.slice(headerIdx + 1);
    out.push(Object.assign({}, ch, { duas: before }));
    queue.unshift({
      num: ch.num,
      arabicTitle: cleanArabicTitle(header.arabic),
      oromoTitle: header.oromo.trim(),
      duas: after,
    });
  }
  return out.map(function (c, i) { return Object.assign({}, c, { num: i + 1 }); });
}

var CHAPTERS = splitEmbeddedChapters(RAW_CHAPTERS)
  .filter(function (c) { return c.duas && c.duas.length > 0; })
  .map(function (c, i) { return Object.assign({}, c, { num: i + 1 }); });

function chapterById(id) {
  for (var i = 0; i < CHAPTERS.length; i++) if (CHAPTERS[i].num === id) return CHAPTERS[i];
  return null;
}

function searchChapters(query) {
  var q = query.trim().toLowerCase();
  if (!q) return CHAPTERS;
  return CHAPTERS.filter(function (c) {
    if (c.oromoTitle.toLowerCase().indexOf(q) !== -1) return true;
    if (c.arabicTitle.indexOf(query) !== -1) return true;
    if (String(c.num) === q) return true;
    return c.duas.some(function (d) {
      return d.oromo.toLowerCase().indexOf(q) !== -1 || d.arabic.indexOf(query) !== -1;
    });
  });
}
